export const EMBEDDED_MIGRATION_FILES: Readonly<Record<string, string>> = Object.freeze({
  "0001_initial.down.sql": "-- Takt — Migration 0001 \"initial\", Rückwärtsrichtung\n-- Reihenfolge: erst Sichten, dann Trigger, dann Tabellen von den Blättern zur Wurzel.\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n\nDROP VIEW IF EXISTS v_export_candidate;\n\nDROP TRIGGER IF EXISTS trg_export_audit_no_delete;\nDROP TRIGGER IF EXISTS trg_export_audit_no_update;\nDROP TRIGGER IF EXISTS trg_export_run_group_no_delete;\nDROP TRIGGER IF EXISTS trg_export_run_group_no_update;\nDROP TRIGGER IF EXISTS trg_export_run_entry_no_delete;\nDROP TRIGGER IF EXISTS trg_export_run_entry_no_update;\nDROP TRIGGER IF EXISTS trg_export_run_no_delete;\nDROP TRIGGER IF EXISTS trg_export_run_no_update;\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_update;\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_delete;\nDROP TRIGGER IF EXISTS trg_time_entry_no_delete_exported;\nDROP TRIGGER IF EXISTS trg_time_entry_locked;\n\nDROP TABLE IF EXISTS app_setting;\nDROP TABLE IF EXISTS export_audit;\nDROP TABLE IF EXISTS export_run_entry;\nDROP TABLE IF EXISTS export_run_group;\nDROP TABLE IF EXISTS export_run;\nDROP TABLE IF EXISTS export_template;\nDROP TABLE IF EXISTS default_tag;\nDROP TABLE IF EXISTS pool_rule;\nDROP TABLE IF EXISTS pool;\nDROP TABLE IF EXISTS time_entry;\nDROP TABLE IF EXISTS todo_tag;\nDROP TABLE IF EXISTS todo_note;\nDROP TABLE IF EXISTS todo;\nDROP TABLE IF EXISTS tag;\nDROP TABLE IF EXISTS tag_folder;\nDROP TABLE IF EXISTS todo_status;\n",
  "0001_initial.up.sql": "-- Takt — Migration 0001 \"initial\", Vorwärtsrichtung\n-- Deckt: A-2.*, A-3.*, A-4.*, A-5.*, A-6.*, A-7.*, A-8.*, A-9.*, E-006, E-008, E-011, E-012\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n\n-- ---------------------------------------------------------------------------\n-- Kanban-Spalten (A-5.3, A-5.4)\n--\n-- Es gibt hier bewusst KEINE Spalte is_done. Erledigt (A-2.4) und die\n-- Kanban-Abschlussspalte (A-5.3) sind zwei getrennte Dinge: Ein Todo kann in\n-- „Done\" stehen und nicht erledigt sein, und es kann erledigt sein und in\n-- „In Progress\" stehen. Das Erledigt-Kennzeichen ist todo.completed_at und\n-- hängt an keiner Spalte.\n--\n-- is_default bleibt: die Spalte, in der ein neu angelegtes Todo landet, wenn\n-- der Aufrufer keine nennt.\n-- ---------------------------------------------------------------------------\nCREATE TABLE todo_status (\n  id          TEXT    NOT NULL PRIMARY KEY,\n  name        TEXT    NOT NULL,\n  position    INTEGER NOT NULL,\n  is_default  INTEGER NOT NULL DEFAULT 0 CHECK (is_default IN (0, 1)),\n  color       TEXT,\n  created_at  TEXT    NOT NULL,\n  updated_at  TEXT    NOT NULL,\n  CHECK (length(trim(name)) > 0)\n);\nCREATE UNIQUE INDEX ux_todo_status_name     ON todo_status (name COLLATE NOCASE);\nCREATE UNIQUE INDEX ux_todo_status_position ON todo_status (position);\n-- Genau eine Spalte ist Standardspalte für neu angelegte Todos.\nCREATE UNIQUE INDEX ux_todo_status_default  ON todo_status ((1)) WHERE is_default = 1;\n\n-- ---------------------------------------------------------------------------\n-- Tag-Ordner: Adjazenzliste, beliebig tief (A-4.2, A-4.3, A-4.6)\n-- ---------------------------------------------------------------------------\nCREATE TABLE tag_folder (\n  id         TEXT NOT NULL PRIMARY KEY,\n  parent_id  TEXT          REFERENCES tag_folder (id) ON DELETE RESTRICT,\n  name       TEXT NOT NULL,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  CHECK (length(trim(name)) > 0),\n  CHECK (parent_id IS NULL OR parent_id <> id)          -- trivialer Selbstzyklus\n);\nCREATE INDEX        ix_tag_folder_parent ON tag_folder (parent_id, name COLLATE NOCASE);\nCREATE UNIQUE INDEX ux_tag_folder_name   ON tag_folder (COALESCE(parent_id, '~root'), name COLLATE NOCASE);\n\n-- ---------------------------------------------------------------------------\n-- Tags (A-4.1, A-4.5)\n-- ---------------------------------------------------------------------------\nCREATE TABLE tag (\n  id         TEXT NOT NULL PRIMARY KEY,\n  folder_id  TEXT          REFERENCES tag_folder (id) ON DELETE RESTRICT,\n  name       TEXT NOT NULL,\n  color      TEXT,\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL,\n  CHECK (length(trim(name)) > 0)\n);\nCREATE INDEX        ix_tag_folder ON tag (folder_id, name COLLATE NOCASE);\nCREATE UNIQUE INDEX ux_tag_name   ON tag (COALESCE(folder_id, '~root'), name COLLATE NOCASE);\n\n-- ---------------------------------------------------------------------------\n-- Todo (A-2.1, A-2.2, A-2.4, E-006)\n-- Der interne Vermerk liegt bewusst NICHT hier, sondern in todo_note (A-7.2, R-06).\n--\n-- completed_at ist das Erledigt-Kennzeichen aus A-2.4 und steht für sich: Es\n-- hängt an keiner Kanban-Spalte, und weder Setzen noch Aufheben verschiebt die\n-- Karte. Deshalb gibt es kein status_id_before_done — es gäbe nichts\n-- wiederherzustellen. A-2.5 trägt die Sichtbarkeit: Erledigte Todos werden in\n-- Pool-Ansichten ausgeblendet, ein aufgehobenes Erledigt bringt das Todo ohne\n-- Zutun in seinen tag-abgeleiteten Pool zurück (A-3.4).\n-- ---------------------------------------------------------------------------\nCREATE TABLE todo (\n  id                     TEXT NOT NULL PRIMARY KEY,\n  title                  TEXT NOT NULL,\n  call_number            TEXT,\n  status_id              TEXT NOT NULL REFERENCES todo_status (id) ON DELETE RESTRICT,\n  board_rank             TEXT NOT NULL,\n  completed_at           TEXT,\n  created_at             TEXT NOT NULL,\n  updated_at             TEXT NOT NULL,\n  CHECK (length(trim(title)) > 0),\n  CHECK (call_number IS NULL OR length(trim(call_number)) > 0),\n  CHECK (completed_at IS NULL OR completed_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z'),\n  CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z')\n);\nCREATE INDEX ix_todo_status      ON todo (status_id, board_rank);\nCREATE INDEX ix_todo_call_number ON todo (call_number) WHERE call_number IS NOT NULL;  -- A-10.9\nCREATE INDEX ix_todo_open        ON todo (updated_at DESC) WHERE completed_at IS NULL;\nCREATE INDEX ix_todo_completed   ON todo (completed_at DESC) WHERE completed_at IS NOT NULL;\nCREATE UNIQUE INDEX ux_todo_rank ON todo (status_id, board_rank);\n\n-- ---------------------------------------------------------------------------\n-- Persönliche Todo-Notiz (A-7.1, A-7.2)\n-- Eigene Tabelle, damit kein Export-Join sie versehentlich mitnehmen kann (R-06).\n-- ---------------------------------------------------------------------------\nCREATE TABLE todo_note (\n  todo_id    TEXT NOT NULL PRIMARY KEY REFERENCES todo (id) ON DELETE CASCADE,\n  body       TEXT NOT NULL DEFAULT '',\n  updated_at TEXT NOT NULL\n) WITHOUT ROWID;\n\n-- ---------------------------------------------------------------------------\n-- Tag-Zuordnung (A-2.3)\n-- ---------------------------------------------------------------------------\nCREATE TABLE todo_tag (\n  todo_id    TEXT NOT NULL REFERENCES todo (id) ON DELETE CASCADE,\n  tag_id     TEXT NOT NULL REFERENCES tag  (id) ON DELETE CASCADE,\n  created_at TEXT NOT NULL,\n  PRIMARY KEY (todo_id, tag_id)\n) WITHOUT ROWID;\nCREATE INDEX ix_todo_tag_reverse ON todo_tag (tag_id, todo_id);\n\n-- ---------------------------------------------------------------------------\n-- Zeitbuchung (A-6.1 bis A-6.9, A-7.3, A-7.4)\n-- ---------------------------------------------------------------------------\nCREATE TABLE time_entry (\n  id               TEXT    NOT NULL PRIMARY KEY,\n  todo_id          TEXT    NOT NULL REFERENCES todo (id) ON DELETE RESTRICT,\n  started_at       TEXT    NOT NULL,\n  ended_at         TEXT,\n  duration_seconds INTEGER GENERATED ALWAYS AS (\n                     CASE WHEN ended_at IS NULL THEN NULL\n                          ELSE unixepoch(ended_at) - unixepoch(started_at) END\n                   ) STORED,\n  note             TEXT    NOT NULL DEFAULT '',\n  export_status    TEXT    NOT NULL DEFAULT 'open'  CHECK (export_status IN ('open', 'exported')),\n  export_count     INTEGER NOT NULL DEFAULT 0       CHECK (export_count >= 0),\n  source           TEXT    NOT NULL DEFAULT 'timer' CHECK (source IN ('timer', 'manual')),\n  created_at       TEXT    NOT NULL,\n  updated_at       TEXT    NOT NULL,\n  CHECK (started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z'),\n  CHECK (ended_at IS NULL OR ended_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z'),\n  CHECK (ended_at IS NULL OR ended_at > started_at),\n  CHECK (duration_seconds IS NULL OR duration_seconds >= 1),   -- E-008: Dauer 0 gibt es nicht\n  CHECK (export_status = 'open' OR ended_at IS NOT NULL),      -- laufend ist nie exportiert\n  CHECK (export_status = 'open' OR export_count >= 1)\n);\n-- A-6.8: höchstens ein laufender Timer, strukturell erzwungen.\nCREATE UNIQUE INDEX ux_time_entry_running ON time_entry ((1)) WHERE ended_at IS NULL;\nCREATE INDEX ix_time_entry_todo   ON time_entry (todo_id, started_at DESC);\nCREATE INDEX ix_time_entry_queue  ON time_entry (todo_id, started_at) WHERE export_status = 'open';\nCREATE INDEX ix_time_entry_day    ON time_entry (started_at DESC);\nCREATE INDEX ix_time_entry_reset  ON time_entry (todo_id) WHERE export_status = 'open' AND export_count > 0;\n\n-- A-6.9: eine exportierte Buchung ist gesperrt. Erlaubt bleibt nur der Wechsel\n-- des Exportstatus selbst (E-012) und das Hochzählen von export_count.\nCREATE TRIGGER trg_time_entry_locked\nBEFORE UPDATE ON time_entry\nWHEN OLD.export_status = 'exported' AND NEW.export_status = 'exported'\n AND (NEW.todo_id    <> OLD.todo_id\n   OR NEW.started_at <> OLD.started_at\n   OR NEW.ended_at   IS NOT OLD.ended_at\n   OR NEW.note       <> OLD.note\n   OR NEW.source     <> OLD.source)\nBEGIN\n  SELECT RAISE(ABORT, 'time_entry_locked');\nEND;\n\n-- Eine exportierte Buchung wird nicht gelöscht, sie wird zurückgesetzt (R-10).\nCREATE TRIGGER trg_time_entry_no_delete_exported\nBEFORE DELETE ON time_entry\nWHEN OLD.export_status = 'exported'\nBEGIN\n  SELECT RAISE(ABORT, 'time_entry_locked');\nEND;\n\n-- ---------------------------------------------------------------------------\n-- Pools (A-3.1 bis A-3.4) — nur die Regel wird gespeichert, nie die Mitgliedschaft.\n-- ---------------------------------------------------------------------------\nCREATE TABLE pool (\n  id                 TEXT    NOT NULL PRIMARY KEY,\n  name               TEXT    NOT NULL,\n  match_mode         TEXT    NOT NULL DEFAULT 'any' CHECK (match_mode IN ('any', 'all')),\n  include_subfolders INTEGER NOT NULL DEFAULT 1     CHECK (include_subfolders IN (0, 1)),\n  position           INTEGER NOT NULL,\n  created_at         TEXT    NOT NULL,\n  updated_at         TEXT    NOT NULL,\n  CHECK (length(trim(name)) > 0)\n);\nCREATE UNIQUE INDEX ux_pool_name     ON pool (name COLLATE NOCASE);\nCREATE UNIQUE INDEX ux_pool_position ON pool (position);\n\nCREATE TABLE pool_rule (\n  pool_id   TEXT NOT NULL REFERENCES pool        (id) ON DELETE CASCADE,\n  tag_id    TEXT          REFERENCES tag         (id) ON DELETE CASCADE,\n  folder_id TEXT          REFERENCES tag_folder  (id) ON DELETE CASCADE,\n  CHECK ((tag_id IS NULL) <> (folder_id IS NULL))     -- genau eine Quelle je Regel\n);\nCREATE UNIQUE INDEX ux_pool_rule ON pool_rule (pool_id, COALESCE(tag_id, ''), COALESCE(folder_id, ''));\nCREATE INDEX        ix_pool_rule_tag    ON pool_rule (tag_id)    WHERE tag_id    IS NOT NULL;\nCREATE INDEX        ix_pool_rule_folder ON pool_rule (folder_id) WHERE folder_id IS NOT NULL;\n\n-- ---------------------------------------------------------------------------\n-- Standard-Tags (A-9.1 bis A-9.5)\n-- ---------------------------------------------------------------------------\nCREATE TABLE default_tag (\n  tag_id     TEXT    NOT NULL PRIMARY KEY REFERENCES tag (id) ON DELETE CASCADE,\n  position   INTEGER NOT NULL,\n  created_at TEXT    NOT NULL\n) WITHOUT ROWID;\nCREATE UNIQUE INDEX ux_default_tag_position ON default_tag (position);\n\n-- ---------------------------------------------------------------------------\n-- Exportvorlagen (A-8.7, E-005). Die Feldliste selbst validiert packages/export.\n-- ---------------------------------------------------------------------------\nCREATE TABLE export_template (\n  id         TEXT    NOT NULL PRIMARY KEY,\n  name       TEXT    NOT NULL,\n  is_builtin INTEGER NOT NULL DEFAULT 0 CHECK (is_builtin IN (0, 1)),\n  definition TEXT    NOT NULL,\n  created_at TEXT    NOT NULL,\n  updated_at TEXT    NOT NULL,\n  CHECK (length(trim(name)) > 0),\n  CHECK (json_valid(definition))\n);\nCREATE UNIQUE INDEX ux_export_template_name    ON export_template (name COLLATE NOCASE);\nCREATE UNIQUE INDEX ux_export_template_builtin ON export_template ((1)) WHERE is_builtin = 1;\n\n-- A-8.7: die Standardvorlage ist nicht löschbar und nicht änderbar, aber kopierbar.\nCREATE TRIGGER trg_export_template_builtin_no_delete\nBEFORE DELETE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n\nCREATE TRIGGER trg_export_template_builtin_no_update\nBEFORE UPDATE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n\n-- ---------------------------------------------------------------------------\n-- Exportlauf (A-8.8) — eine Zeile je geschriebener Datei.\n-- ---------------------------------------------------------------------------\nCREATE TABLE export_run (\n  id                TEXT    NOT NULL PRIMARY KEY,\n  template_id       TEXT    NOT NULL REFERENCES export_template (id) ON DELETE RESTRICT,\n  template_snapshot TEXT    NOT NULL,\n  file_path         TEXT    NOT NULL,\n  file_sha256       TEXT    NOT NULL,\n  byte_size         INTEGER NOT NULL CHECK (byte_size > 0),\n  entry_count       INTEGER NOT NULL CHECK (entry_count > 0),\n  total_quarters    INTEGER NOT NULL CHECK (total_quarters > 0),\n  rounding_mode     TEXT    NOT NULL CHECK (rounding_mode IN ('up', 'nearest')),\n  windows_user      TEXT    NOT NULL,\n  created_at        TEXT    NOT NULL,\n  CHECK (json_valid(template_snapshot)),\n  CHECK (file_sha256 GLOB '[0-9a-f]*' AND length(file_sha256) = 64)\n);\nCREATE INDEX ix_export_run_created ON export_run (created_at DESC);\n\nCREATE TRIGGER trg_export_run_no_update BEFORE UPDATE ON export_run\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\nCREATE TRIGGER trg_export_run_no_delete BEFORE DELETE ON export_run\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\n\n-- Eine Exportgruppe: ein Todo an einem Kalendertag, eine Zeile in der Datei.\n--\n-- Der gerundete Wert hängt hier und nicht an der einzelnen Buchung. Bei 10, 20\n-- und 5 Minuten in einer Gruppe von 0,75 gibt es keine richtige Aufteilung auf\n-- die drei Buchungen, nur mehrere falsche — und eine willkürliche Aufteilung\n-- würde genau das Protokoll verfälschen, das R-10 nachvollziehbar halten soll.\n--\n-- `seconds` ist die ungerundete Summe, `quarters` der Wert, der in die\n-- Abrechnung ging. Beide zusammen machen nachrechenbar, wieviel die Rundung\n-- der Zeile hinzugefügt hat.\nCREATE TABLE export_run_group (\n  id            TEXT    NOT NULL PRIMARY KEY,\n  export_run_id TEXT    NOT NULL REFERENCES export_run (id) ON DELETE RESTRICT,\n  todo_id       TEXT    NOT NULL REFERENCES todo       (id) ON DELETE RESTRICT,\n  day           TEXT    NOT NULL,\n  seconds       INTEGER NOT NULL CHECK (seconds  >= 1),\n  quarters      INTEGER NOT NULL CHECK (quarters >= 1),\n  CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]')\n);\n-- Je Lauf höchstens eine Gruppe für dasselbe Todo am selben Tag.\nCREATE UNIQUE INDEX ux_export_run_group      ON export_run_group (export_run_id, todo_id, day);\nCREATE INDEX        ix_export_run_group_todo ON export_run_group (todo_id, day);\n\nCREATE TRIGGER trg_export_run_group_no_update BEFORE UPDATE ON export_run_group\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\nCREATE TRIGGER trg_export_run_group_no_delete BEFORE DELETE ON export_run_group\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\n\n-- Welche Buchungen in welche Zeile eingegangen sind.\n--\n-- `duration_seconds` ist die ungerundete Dauer der Buchung, nicht ihr Anteil an\n-- den Viertelstunden der Gruppe. Ein Anteil existiert nicht.\nCREATE TABLE export_run_entry (\n  export_run_group_id TEXT    NOT NULL REFERENCES export_run_group (id) ON DELETE RESTRICT,\n  time_entry_id       TEXT    NOT NULL REFERENCES time_entry       (id) ON DELETE RESTRICT,\n  duration_seconds    INTEGER NOT NULL CHECK (duration_seconds >= 1),\n  PRIMARY KEY (export_run_group_id, time_entry_id)\n) WITHOUT ROWID;\nCREATE INDEX ix_export_run_entry_time_entry ON export_run_entry (time_entry_id);\n\nCREATE TRIGGER trg_export_run_entry_no_update BEFORE UPDATE ON export_run_entry\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\nCREATE TRIGGER trg_export_run_entry_no_delete BEFORE DELETE ON export_run_entry\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\n\n-- ---------------------------------------------------------------------------\n-- Exportstatus-Protokoll (E-012, R-10) — anhängend und unveränderlich.\n-- ---------------------------------------------------------------------------\n-- Kein Feld `quarters`. Der gerundete Wert gehört der Gruppe, nicht der\n-- Buchung; das Protokoll verweist deshalb auf die Gruppe, statt einen Anteil zu\n-- erfinden. Über export_run_group_id sind Tagessumme und gerundeter Wert der\n-- Zeile erreichbar, in der die Buchung damals stand.\nCREATE TABLE export_audit (\n  id                  TEXT NOT NULL PRIMARY KEY,\n  time_entry_id       TEXT NOT NULL REFERENCES time_entry       (id) ON DELETE RESTRICT,\n  event               TEXT NOT NULL CHECK (event           IN ('exported', 'reset')),\n  previous_status     TEXT NOT NULL CHECK (previous_status IN ('open', 'exported')),\n  new_status          TEXT NOT NULL CHECK (new_status      IN ('open', 'exported')),\n  export_run_id       TEXT          REFERENCES export_run       (id) ON DELETE RESTRICT,\n  export_run_group_id TEXT          REFERENCES export_run_group (id) ON DELETE RESTRICT,\n  actor               TEXT NOT NULL,\n  reason              TEXT NOT NULL DEFAULT '',\n  occurred_at         TEXT NOT NULL,\n  CHECK (previous_status <> new_status),\n  CHECK ((event = 'exported' AND export_run_id       IS NOT NULL\n                             AND export_run_group_id IS NOT NULL\n                             AND new_status = 'exported')\n      OR (event = 'reset'    AND export_run_id       IS NULL\n                             AND export_run_group_id IS NULL\n                             AND new_status = 'open'))\n);\nCREATE INDEX ix_export_audit_entry ON export_audit (time_entry_id, occurred_at DESC);\nCREATE INDEX ix_export_audit_time  ON export_audit (occurred_at DESC);\n\nCREATE TRIGGER trg_export_audit_no_update BEFORE UPDATE ON export_audit\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\nCREATE TRIGGER trg_export_audit_no_delete BEFORE DELETE ON export_audit\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\n\n-- ---------------------------------------------------------------------------\n-- Einstellungen (E-011). Einzeiler-Tabelle, kein Schlüssel-Wert-Beutel.\n-- Das Add-in-Token liegt bewusst NICHT hier, sondern in einer eigenen Datei (E-009).\n-- ---------------------------------------------------------------------------\nCREATE TABLE app_setting (\n  id                       INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),\n  export_directory         TEXT,\n  active_export_template_id TEXT   REFERENCES export_template (id) ON DELETE SET NULL,\n  rounding_mode            TEXT    NOT NULL DEFAULT 'up' CHECK (rounding_mode IN ('up', 'nearest')),\n  locale                   TEXT    NOT NULL DEFAULT 'de-DE',\n  theme                    TEXT    NOT NULL DEFAULT 'system' CHECK (theme IN ('system', 'light', 'dark')),\n  updated_at               TEXT    NOT NULL\n);\n\n-- ---------------------------------------------------------------------------\n-- Exportsicht (A-7.2, R-06): die einzige Quelle, die der Exportmotor liest.\n-- Sie enthält keine Spalte todo_note.body — die Grenze ist im Schema, nicht im Code.\n-- ---------------------------------------------------------------------------\nCREATE VIEW v_export_candidate AS\nSELECT\n  te.id               AS time_entry_id,\n  te.todo_id          AS todo_id,\n  te.started_at       AS started_at,\n  te.ended_at         AS ended_at,\n  te.duration_seconds AS duration_seconds,\n  te.note             AS booking_note,\n  te.export_count     AS export_count,\n  t.title             AS todo_title,\n  t.call_number       AS todo_call_number\nFROM time_entry te\nJOIN todo t ON t.id = te.todo_id\nWHERE te.export_status = 'open'\n  AND te.ended_at IS NOT NULL;\n",
  "0002_seed_defaults.down.sql": "-- Takt — Migration 0002 \"seed_defaults\", Rückwärtsrichtung\n--\n-- Eine Datenmigration ist nur so lange rücknehmbar, wie niemand auf die\n-- angelegten Zeilen verweist. Sobald ein Todo in einer der vier Beispielspalten\n-- liegt oder ein Exportlauf die Standardvorlage benutzt hat, ist die Rücknahme\n-- verlustbehaftet. Sie bricht dann ausdrücklich ab, statt still zu scheitern\n-- oder Daten zu zerstören. Der Rückweg auf einem benutzten Bestand ist die\n-- Sicherungskopie, die der Migrationsläufer vor jedem Lauf anlegt.\n\n-- Wächter: erzwingt einen sprechenden Abbruch statt eines rohen\n-- FOREIGN-KEY-Fehlers. Schlägt der CHECK fehl, rollt die umschließende\n-- Transaktion des Läufers alles zurück.\nCREATE TEMP TABLE _rollback_0002_guard (\n  ok INTEGER NOT NULL\n    CONSTRAINT rollback_0002_only_without_user_data CHECK (ok = 1)\n);\n\nINSERT INTO _rollback_0002_guard (ok)\nSELECT CASE WHEN (SELECT count(*) FROM todo)       = 0\n             AND (SELECT count(*) FROM export_run) = 0\n            THEN 1 ELSE 0 END;\n\nDROP TABLE _rollback_0002_guard;\n\nUPDATE app_setting SET active_export_template_id = NULL WHERE id = 1;\nDELETE FROM app_setting WHERE id = 1;\n\n-- Die Trigger auf export_template verbieten das Löschen der Standardvorlage.\n-- Sie werden für die Dauer der Rücknahme entfernt und danach wiederhergestellt.\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_delete;\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_update;\n\nDELETE FROM export_template WHERE is_builtin = 1;\n\nCREATE TRIGGER trg_export_template_builtin_no_delete\nBEFORE DELETE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n\nCREATE TRIGGER trg_export_template_builtin_no_update\nBEFORE UPDATE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n\nDELETE FROM todo_status WHERE id IN (\n  '01931000-0000-7000-8000-000000000001',\n  '01931000-0000-7000-8000-000000000002',\n  '01931000-0000-7000-8000-000000000003',\n  '01931000-0000-7000-8000-000000000004');\n",
  "0002_seed_defaults.up.sql": "-- Takt — Migration 0002 \"seed_defaults\", Vorwärtsrichtung\n-- Datenmigration, getrennt von der Schemamigration 0001.\n-- Legt an: die vier Beispielspalten aus A-5.3, die Einstellungszeile und die\n-- nicht löschbare Standard-Exportvorlage aus A-8.2 bis A-8.5.\n-- Die Feldliste ist die Speicherform aus E-005; packages/export validiert sie.\n-- Die Schluessel Call/Zeit/Notiz/WindowsUser gibt das Abrechnungstool vor und\n-- bleiben deutsch (A-8.2). Die Transformationsnamen sind technische Werte und\n-- daher englisch: raw, round_to_quarter_hour, base64.\n\n-- Die Spalte „Done\" ist eine Spalte wie jede andere. Sie trägt keine Markierung,\n-- die sie mit dem Erledigt-Kennzeichen aus A-2.4 verknüpft — beides ist\n-- getrennt. Standardspalte für neu angelegte Todos ist „Backlog\".\nINSERT INTO todo_status (id, name, position, is_default, color, created_at, updated_at) VALUES\n  ('01931000-0000-7000-8000-000000000001', 'Backlog',     1, 1, '#64748b', '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z'),\n  ('01931000-0000-7000-8000-000000000002', 'In Progress', 2, 0, '#2563eb', '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z'),\n  ('01931000-0000-7000-8000-000000000003', 'Waiting',     3, 0, '#d97706', '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z'),\n  ('01931000-0000-7000-8000-000000000004', 'Done',        4, 0, '#16a34a', '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z');\n\nINSERT INTO export_template (id, name, is_builtin, definition, created_at, updated_at) VALUES\n  ('01931000-0000-7000-8000-0000000000f1', 'Standard', 1,\n   json('{\"version\":1,\"fields\":['\n     || '{\"name\":\"Call\",\"source\":\"todo.callNumber\",\"transform\":\"raw\"},'\n     || '{\"name\":\"Zeit\",\"source\":\"booking.durationSeconds\",\"transform\":\"round_to_quarter_hour\"},'\n     || '{\"name\":\"Notiz\",\"source\":\"booking.note\",\"transform\":\"base64\"},'\n     || '{\"name\":\"WindowsUser\",\"source\":\"system.windowsUser\",\"transform\":\"raw\"}]}'),\n   '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z');\n\nINSERT INTO app_setting (id, export_directory, active_export_template_id, rounding_mode, locale, theme, updated_at)\nVALUES (1, NULL, '01931000-0000-7000-8000-0000000000f1', 'up', 'de-DE', 'system', '2026-01-01T00:00:00Z');\n",
  "0003_timer_heartbeat.down.sql": "-- Takt — Migration 0003 \"timer_heartbeat\", Rückwärtsrichtung\n-- Reihenfolge: erst die Trigger, dann die Tabelle.\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- Verlustfrei im fachlichen Sinn: Das Lebenszeichen ist ein flüchtiger Wert für\n-- einen gerade laufenden Timer. Es geht keine erfasste Arbeitszeit verloren —\n-- die Buchungen selbst stehen in time_entry und bleiben unberührt. Nach der\n-- Rücknahme verhält sich Takt wie vor E-036: Ein verwaister Timer ist dann\n-- nicht mehr bis zum letzten Lebenszeichen buchbar, sondern nur noch zu\n-- verwerfen.\n\nDROP TRIGGER IF EXISTS trg_timer_heartbeat_only_running_update;\nDROP TRIGGER IF EXISTS trg_timer_heartbeat_only_running_insert;\n\nDROP TABLE IF EXISTS timer_heartbeat;\n",
  "0003_timer_heartbeat.up.sql": "-- Takt — Migration 0003 \"timer_heartbeat\", Vorwärtsrichtung\n-- Deckt: E-036, A-6.4. Auflage aus T-009.\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- ---------------------------------------------------------------------------\n-- Warum eine eigene Tabelle und keine Spalte auf time_entry\n-- ---------------------------------------------------------------------------\n--\n-- E-036 verlangt, dass ein laufender Timer im Betrieb mindestens jede Minute\n-- ein Lebenszeichen hinterlässt. Beim nächsten Start erkennt Takt die verwaiste\n-- Buchung und bucht höchstens bis zu diesem Zeitpunkt — statt einen über Nacht\n-- vergessenen Timer vierzehn Stunden weiterzuzählen, die nach der Aufrundung\n-- aus E-008 in einer Rechnung landen.\n--\n-- Drei Gründe sprechen gegen eine Spalte auf time_entry:\n--\n--  1. Ein Schreibvorgang je Minute auf eine Zeile, die Abrechnungsdaten trägt,\n--     berührt genau die Zeile, die der Sperr-Trigger aus A-6.9 schützt. Die\n--     Trennung hält den heißen Pfad von den kalten Daten fern.\n--  2. Die Spalte müsste in der Rückwärtsrichtung wieder verschwinden. SQLite\n--     verweigert DROP COLUMN, sobald die Spalte in einem CHECK vorkommt — der\n--     Rückweg wäre also entweder ein vollständiger Tabellenumbau oder eine\n--     Spalte ohne Formatprüfung. Eine eigene Tabelle kostet ein DROP TABLE.\n--  3. Der Wert ist flüchtig. Er gilt für genau einen laufenden Timer, hat nach\n--     dessen Ende keine Bedeutung mehr und gehört deshalb nicht in die\n--     Buchung, die dauerhaft aufbewahrt wird.\n--\n-- Höchstens eine Zeile existiert gleichzeitig: Es gibt höchstens einen\n-- laufenden Timer (A-6.8, ux_time_entry_running), und der Primärschlüssel\n-- bindet das Lebenszeichen an genau dessen Buchung.\n--\n-- ON DELETE CASCADE: Wird eine verworfene Buchung gelöscht, verschwindet ihr\n-- Lebenszeichen mit. Eine exportierte Buchung lässt sich ohnehin nicht löschen\n-- (trg_time_entry_no_delete_exported), und eine laufende war nie exportiert.\n-- ---------------------------------------------------------------------------\n\nCREATE TABLE timer_heartbeat (\n  time_entry_id TEXT NOT NULL PRIMARY KEY REFERENCES time_entry (id) ON DELETE CASCADE,\n  seen_at       TEXT NOT NULL,\n  CHECK (seen_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z')\n);\n\n-- Ein Lebenszeichen für eine bereits beendete Buchung ist sinnlos und wäre ein\n-- Hinweis auf einen Fehler im Adapter: Geschrieben wird nur, solange der Timer\n-- läuft. Der Trigger fängt beides ab, Einfügen wie Fortschreiben.\nCREATE TRIGGER trg_timer_heartbeat_only_running_insert\nBEFORE INSERT ON timer_heartbeat\nWHEN (SELECT ended_at FROM time_entry WHERE id = NEW.time_entry_id) IS NOT NULL\nBEGIN\n  SELECT RAISE(ABORT, 'timer_not_running');\nEND;\n\nCREATE TRIGGER trg_timer_heartbeat_only_running_update\nBEFORE UPDATE ON timer_heartbeat\nWHEN (SELECT ended_at FROM time_entry WHERE id = NEW.time_entry_id) IS NOT NULL\nBEGIN\n  SELECT RAISE(ABORT, 'timer_not_running');\nEND;\n",
  "0004_builtin_template_group_sources.down.sql": "-- Takt — Migration 0004 \"builtin_template_group_sources\", Rückwärtsrichtung\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- Stellt die Feldliste aus 0002 wortgleich wieder her. Verlustfrei: Geändert\n-- wird ausschließlich die mitgelieferte Vorlage, keine vom Benutzer angelegte\n-- Kopie (A-8.7) und kein `template_snapshot` eines gelaufenen Exports — der ist\n-- unveränderlich und trägt weiterhin die Fassung, mit der er tatsächlich\n-- geschrieben wurde.\n--\n-- Nach der Rücknahme zeigt die Standardvorlage wieder auf `booking.*`. Das ist\n-- kein Versehen, sondern der Sinn einer Rückwärtsmigration: Sie stellt den\n-- Stand von 0002 her, einschließlich seiner Fehler.\n\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_delete;\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_update;\n\nUPDATE export_template\n   SET definition = json('{\"version\":1,\"fields\":['\n         || '{\"name\":\"Call\",\"source\":\"todo.callNumber\",\"transform\":\"raw\"},'\n         || '{\"name\":\"Zeit\",\"source\":\"booking.durationSeconds\",\"transform\":\"round_to_quarter_hour\"},'\n         || '{\"name\":\"Notiz\",\"source\":\"booking.note\",\"transform\":\"base64\"},'\n         || '{\"name\":\"WindowsUser\",\"source\":\"system.windowsUser\",\"transform\":\"raw\"}]}'),\n       updated_at = '2026-01-01T00:00:00Z'\n WHERE id = '01931000-0000-7000-8000-0000000000f1'\n   AND is_builtin = 1;\n\nCREATE TRIGGER trg_export_template_builtin_no_delete\nBEFORE DELETE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n\nCREATE TRIGGER trg_export_template_builtin_no_update\nBEFORE UPDATE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n",
  "0004_builtin_template_group_sources.up.sql": "-- Takt — Migration 0004 \"builtin_template_group_sources\", Vorwärtsrichtung\n-- Deckt: E-020, E-026, E-033. Auflage aus T-009.\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- ---------------------------------------------------------------------------\n-- Warum die Standardvorlage nachgezogen wird\n-- ---------------------------------------------------------------------------\n--\n-- Migration 0002 hat die Standardvorlage mit den Quellen `booking.durationSeconds`\n-- und `booking.note` angelegt. Das war der Stand vor E-020: eine Exportzeile je\n-- Buchung. Seither entsteht eine Zeile je Todo und Kalendertag, und E-033 hat\n-- `booking.*` in `ExportSourcePath` (packages/domain/src/export.ts) **entfernt**\n-- statt umgedeutet — abgesichert durch die Typbehauptung `BookingSourcesAreGone`.\n--\n-- Damit zeigt die mitgelieferte, nicht löschbare Vorlage auf zwei Quellen, die\n-- es in der Domäne nicht mehr gibt. Der Vorlagen-Motor weist sie mit\n-- `export_source_forbidden` ab: Die Standardvorlage wäre unbenutzbar, und zwar\n-- ausgerechnet die eine, die der Benutzer nicht löschen und nicht reparieren\n-- kann (A-8.7).\n--\n-- Ersetzt wird:\n--\n--   Zeit   booking.durationSeconds -> group.quarters\n--          Die **gerundete** Tagessumme der Gruppe (E-008, E-020). Erst\n--          addieren, dann runden — 10, 20 und 5 Minuten am selben Tag ergeben\n--          0,75 und nicht dreimal aufgerundet 1,00.\n--   Notiz  booking.note            -> group.bookingNotes\n--          Die nach Startzeit sortierten und mit \"; \" verbundenen\n--          Leistungstexte der Gruppe (E-026, E-028). Base64 wird auf den\n--          zusammengeführten Text angewandt, nicht je Einzeltext.\n--\n-- Die Transformation für `Zeit` heißt jetzt `quarter_hours_to_number` statt\n-- `round_to_quarter_hour`. Das ist kein Schönheitswechsel: Die alte\n-- Transformation bekam Sekunden und rundete sie; die neue bekommt eine bereits\n-- gerundete Anzahl Viertelstunden und teilt sie durch vier. Bliebe der alte\n-- Name stehen, würde eine Umsetzung, die ihn wörtlich nimmt, die Zahl 3 als\n-- Sekunden lesen und daraus 0,25 machen — aus 0,75 würde still 0,25 auf einer\n-- Kundenrechnung. Ein unbekannter Name bricht sichtbar beim Validieren, ein\n-- umgedeuteter bricht still und erst beim Abrechnen. Genau das ist die\n-- Begründung aus E-033, eine Ebene tiefer.\n--\n-- Die Trigger auf export_template verbieten jede Änderung an der\n-- Standardvorlage (A-8.7). Sie werden für die Dauer der Migration entfernt und\n-- danach wortgleich wiederhergestellt — wie schon in der Rückwärtsrichtung von\n-- 0002.\n-- ---------------------------------------------------------------------------\n\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_delete;\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_update;\n\nUPDATE export_template\n   SET definition = json('{\"version\":1,\"fields\":['\n         || '{\"name\":\"Call\",\"source\":\"todo.callNumber\",\"transform\":\"raw\"},'\n         || '{\"name\":\"Zeit\",\"source\":\"group.quarters\",\"transform\":\"quarter_hours_to_number\"},'\n         || '{\"name\":\"Notiz\",\"source\":\"group.bookingNotes\",\"transform\":\"base64\"},'\n         || '{\"name\":\"WindowsUser\",\"source\":\"system.windowsUser\",\"transform\":\"raw\"}]}'),\n       updated_at = '2026-09-01T00:00:00Z'\n WHERE id = '01931000-0000-7000-8000-0000000000f1'\n   AND is_builtin = 1;\n\nCREATE TRIGGER trg_export_template_builtin_no_delete\nBEFORE DELETE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n\nCREATE TRIGGER trg_export_template_builtin_no_update\nBEFORE UPDATE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n",
  "0005_builtin_template_field_key.down.sql": "-- Takt — Migration 0005 \"builtin_template_field_key\", Rückwärtsrichtung\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- Stellt die Feldliste aus 0004 wortgleich wieder her, einschließlich des\n-- Schlüssels `transform`. Verlustfrei: Geändert wird ausschließlich die\n-- mitgelieferte Vorlage, keine vom Benutzer angelegte Kopie und kein\n-- `template_snapshot` eines gelaufenen Exports — der ist unveränderlich und\n-- trägt weiterhin die Fassung, mit der er tatsächlich geschrieben wurde.\n\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_delete;\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_update;\n\nUPDATE export_template\n   SET definition = json('{\"version\":1,\"fields\":['\n         || '{\"name\":\"Call\",\"source\":\"todo.callNumber\",\"transform\":\"raw\"},'\n         || '{\"name\":\"Zeit\",\"source\":\"group.quarters\",\"transform\":\"quarter_hours_to_number\"},'\n         || '{\"name\":\"Notiz\",\"source\":\"group.bookingNotes\",\"transform\":\"base64\"},'\n         || '{\"name\":\"WindowsUser\",\"source\":\"system.windowsUser\",\"transform\":\"raw\"}]}'),\n       updated_at = '2026-09-01T00:00:00Z'\n WHERE id = '01931000-0000-7000-8000-0000000000f1'\n   AND is_builtin = 1;\n\nCREATE TRIGGER trg_export_template_builtin_no_delete\nBEFORE DELETE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n\nCREATE TRIGGER trg_export_template_builtin_no_update\nBEFORE UPDATE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n",
  "0005_builtin_template_field_key.up.sql": "-- Takt — Migration 0005 \"builtin_template_field_key\", Vorwärtsrichtung\n-- Deckt: E-005, E-015. Auflage aus T-009 (Nachtrag), gemeldet vom Orchestrator.\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- ---------------------------------------------------------------------------\n-- Der Schlüssel heißt \"transformation\", nicht \"transform\"\n-- ---------------------------------------------------------------------------\n--\n-- Migration 0002 und 0004 schrieben \"transform\". Der einzige Typ, der das Feld\n-- überhaupt benennt, ist `ExportFieldDefinition` in `packages/export/src/model.ts`\n-- (T-007), und der heißt `transformation`. `packages/domain/src/export.ts` sagt\n-- dazu bewusst nichts: `ExportTemplateEnvelope.definition` ist `unknown`, weil\n-- das Vorlagenformat dem Motor gehört und nicht der Domäne — es soll sich\n-- weiterentwickeln können, ohne dass Schema oder Domäne mitwandern.\n--\n-- Damit gewinnt der Typ, und die Migration zieht nach. Die umgekehrte Richtung\n-- wäre schlechter gewesen: Ein in SQL festgeschriebener Feldname zwänge den\n-- Motor, sein eigenes Format nach der Datenbank zu benennen, und genau diese\n-- Kopplung vermeidet `definition unknown`.\n--\n-- Die Werte bleiben englisch (E-015, „Bezeichner im Code englisch\"): `raw`,\n-- `base64`, `quarter_hours_to_number`. Das ist keine Änderung gegenüber 0004,\n-- sondern die Bestätigung dessen, was dort schon steht.\n--\n-- Ohne diesen Schritt ist die nicht löschbare Standardvorlage für den\n-- Vorlagen-Motor unlesbar: Er sucht `transformation`, findet nichts und weist\n-- das Feld mit `validation_error` ab (A-8.7 — der Benutzer kann diese Vorlage\n-- weder löschen noch reparieren).\n--\n-- Die Trigger auf export_template verbieten jede Änderung an der\n-- Standardvorlage. Sie werden für die Dauer der Migration entfernt und danach\n-- wortgleich wiederhergestellt, wie in 0004 und in der Rückwärtsrichtung von\n-- 0002.\n-- ---------------------------------------------------------------------------\n\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_delete;\nDROP TRIGGER IF EXISTS trg_export_template_builtin_no_update;\n\nUPDATE export_template\n   SET definition = json('{\"version\":1,\"fields\":['\n         || '{\"name\":\"Call\",\"source\":\"todo.callNumber\",\"transformation\":\"raw\"},'\n         || '{\"name\":\"Zeit\",\"source\":\"group.quarters\",\"transformation\":\"quarter_hours_to_number\"},'\n         || '{\"name\":\"Notiz\",\"source\":\"group.bookingNotes\",\"transformation\":\"base64\"},'\n         || '{\"name\":\"WindowsUser\",\"source\":\"system.windowsUser\",\"transformation\":\"raw\"}]}'),\n       updated_at = '2026-09-01T00:00:00Z'\n WHERE id = '01931000-0000-7000-8000-0000000000f1'\n   AND is_builtin = 1;\n\nCREATE TRIGGER trg_export_template_builtin_no_delete\nBEFORE DELETE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n\nCREATE TRIGGER trg_export_template_builtin_no_update\nBEFORE UPDATE ON export_template WHEN OLD.is_builtin = 1\nBEGIN SELECT RAISE(ABORT, 'builtin_template_immutable'); END;\n",
  "0006_not_billed_audit_event.down.sql": "-- Takt — Migration 0006 \"not_billed_audit_event\", Rückwärtsrichtung\n-- takt: foreign_keys=off\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n-- Zum Verfahren des Tabellenumbaus und zur Marke in Zeile 2 siehe den Kopf der\n-- Vorwärtsdatei.\n--\n-- Stellt den CHECK aus 0001 wortgleich wieder her: nur 'exported' und 'reset'.\n--\n-- **Nur verlustfrei, solange niemand ausgebucht hat.** Eine Zeile mit\n-- event='not_billed' hat unter dem alten CHECK keinen Platz — sie wäre entweder\n-- zu verwerfen oder als 'exported' ohne Exportlauf umzudeuten, und beides wäre\n-- schlimmer als ein Abbruch: Das eine löscht die Auskunft „diese Zeit wurde nie\n-- abgerechnet\", das andere verfälscht sie zu „wurde exportiert\" und erfindet\n-- damit einen Beleg, den es nie gab.\n--\n-- Die Rücknahme bricht deshalb ausdrücklich ab, sobald eine solche Zeile\n-- existiert. Der Rückweg auf einem benutzten Bestand ist die Sicherungskopie,\n-- die der Läufer vor jedem Vorwärtslauf anlegt (datenmodell.md 8.3).\n--\n-- Der Wächter prüft beides: die Protokollzeile **und** die Buchung, die unter\n-- dem zurückkehrenden CHECK `export_status = 'open' OR export_count >= 1`\n-- keinen Platz hätte. Die zweite Bedingung ist nach heutigem Stand von der\n-- ersten miterfasst; sie steht trotzdem da, weil sie genau das prüft, was die\n-- Tabelle gleich wieder verlangen wird, statt sich auf eine Herleitung zu\n-- verlassen.\n\n-- Wächter: erzwingt einen sprechenden Abbruch statt eines rohen CHECK-Fehlers\n-- mitten im Kopieren.\nCREATE TEMP TABLE _rollback_0006_guard (\n  ok INTEGER NOT NULL\n    CONSTRAINT rollback_0006_only_without_not_billed CHECK (ok = 1)\n);\n\nINSERT INTO _rollback_0006_guard (ok)\nSELECT CASE WHEN (SELECT count(*) FROM export_audit WHERE event = 'not_billed') = 0\n             AND (SELECT count(*) FROM time_entry\n                   WHERE export_status = 'exported' AND export_count = 0) = 0\n            THEN 1 ELSE 0 END;\n\nDROP TABLE _rollback_0006_guard;\n\n-- Die beiden folgenden Zeilen sind kein Widerspruch zur Marke in Zeile 2,\n-- sondern ihre Ergänzung: `PRAGMA foreign_keys` ist **innerhalb** einer\n-- offenen Transaktion wirkungslos. Läuft diese Datei über den Migrationsläufer,\n-- ist die Prüfung durch die Marke bereits vor BEGIN abgeschaltet und diese Zeile\n-- tut nichts. Wird sie ohne Läufer eingespielt — so machen es die Prüfpfade, die\n-- das Schema selbst untersuchen —, gibt es keine offene Transaktion, und dann\n-- ist genau diese Zeile die wirksame. Ohne sie zöge das RENAME weiter unten die\n-- REFERENCES-Klauseln der Kindtabellen mit auf die weggeworfene Tabelle.\nPRAGMA foreign_keys = OFF;\n\nPRAGMA legacy_alter_table = ON;\n\nCREATE TABLE export_audit_alt (\n  id                  TEXT NOT NULL PRIMARY KEY,\n  time_entry_id       TEXT NOT NULL REFERENCES time_entry       (id) ON DELETE RESTRICT,\n  event               TEXT NOT NULL CHECK (event           IN ('exported', 'reset')),\n  previous_status     TEXT NOT NULL CHECK (previous_status IN ('open', 'exported')),\n  new_status          TEXT NOT NULL CHECK (new_status      IN ('open', 'exported')),\n  export_run_id       TEXT          REFERENCES export_run       (id) ON DELETE RESTRICT,\n  export_run_group_id TEXT          REFERENCES export_run_group (id) ON DELETE RESTRICT,\n  actor               TEXT NOT NULL,\n  reason              TEXT NOT NULL DEFAULT '',\n  occurred_at         TEXT NOT NULL,\n  CHECK (previous_status <> new_status),\n  CHECK ((event = 'exported' AND export_run_id       IS NOT NULL\n                             AND export_run_group_id IS NOT NULL\n                             AND new_status = 'exported')\n      OR (event = 'reset'    AND export_run_id       IS NULL\n                             AND export_run_group_id IS NULL\n                             AND new_status = 'open'))\n);\n\nINSERT INTO export_audit_alt\n  (id, time_entry_id, event, previous_status, new_status,\n   export_run_id, export_run_group_id, actor, reason, occurred_at)\nSELECT\n   id, time_entry_id, event, previous_status, new_status,\n   export_run_id, export_run_group_id, actor, reason, occurred_at\n  FROM export_audit;\n\nDROP TABLE export_audit;\n\nALTER TABLE export_audit_alt RENAME TO export_audit;\n\nCREATE INDEX ix_export_audit_entry ON export_audit (time_entry_id, occurred_at DESC);\nCREATE INDEX ix_export_audit_time  ON export_audit (occurred_at DESC);\n\nCREATE TRIGGER trg_export_audit_no_update BEFORE UPDATE ON export_audit\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\nCREATE TRIGGER trg_export_audit_no_delete BEFORE DELETE ON export_audit\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\n\n-- ---------------------------------------------------------------------------\n-- Zweiter Teil: der Zähler-CHECK auf time_entry kehrt zurück\n-- ---------------------------------------------------------------------------\n--\n-- Spiegelbild des Vorwärtsschritts, mit demselben Verfahren. Der Wächter oben\n-- hat bereits sichergestellt, dass keine Zeile den zurückkehrenden CHECK\n-- verletzt.\n\nDROP TRIGGER IF EXISTS trg_time_entry_exported_needs_provenance;\n\nALTER TABLE time_entry RENAME TO time_entry_alt;\n\nCREATE TABLE time_entry (\n  id               TEXT    NOT NULL PRIMARY KEY,\n  todo_id          TEXT    NOT NULL REFERENCES todo (id) ON DELETE RESTRICT,\n  started_at       TEXT    NOT NULL,\n  ended_at         TEXT,\n  duration_seconds INTEGER GENERATED ALWAYS AS (\n                     CASE WHEN ended_at IS NULL THEN NULL\n                          ELSE unixepoch(ended_at) - unixepoch(started_at) END\n                   ) STORED,\n  note             TEXT    NOT NULL DEFAULT '',\n  export_status    TEXT    NOT NULL DEFAULT 'open'  CHECK (export_status IN ('open', 'exported')),\n  export_count     INTEGER NOT NULL DEFAULT 0       CHECK (export_count >= 0),\n  source           TEXT    NOT NULL DEFAULT 'timer' CHECK (source IN ('timer', 'manual')),\n  created_at       TEXT    NOT NULL,\n  updated_at       TEXT    NOT NULL,\n  CHECK (started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z'),\n  CHECK (ended_at IS NULL OR ended_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z'),\n  CHECK (ended_at IS NULL OR ended_at > started_at),\n  CHECK (duration_seconds IS NULL OR duration_seconds >= 1),   -- E-008: Dauer 0 gibt es nicht\n  CHECK (export_status = 'open' OR ended_at IS NOT NULL),      -- laufend ist nie exportiert\n  CHECK (export_status = 'open' OR export_count >= 1)\n);\n\nINSERT INTO time_entry\n  (id, todo_id, started_at, ended_at, note, export_status, export_count, source, created_at, updated_at)\nSELECT\n   id, todo_id, started_at, ended_at, note, export_status, export_count, source, created_at, updated_at\n  FROM time_entry_alt;\n\nDROP TABLE time_entry_alt;\n\nCREATE UNIQUE INDEX ux_time_entry_running ON time_entry ((1)) WHERE ended_at IS NULL;\nCREATE INDEX ix_time_entry_todo   ON time_entry (todo_id, started_at DESC);\nCREATE INDEX ix_time_entry_queue  ON time_entry (todo_id, started_at) WHERE export_status = 'open';\nCREATE INDEX ix_time_entry_day    ON time_entry (started_at DESC);\nCREATE INDEX ix_time_entry_reset  ON time_entry (todo_id) WHERE export_status = 'open' AND export_count > 0;\n\nCREATE TRIGGER trg_time_entry_locked\nBEFORE UPDATE ON time_entry\nWHEN OLD.export_status = 'exported' AND NEW.export_status = 'exported'\n AND (NEW.todo_id    <> OLD.todo_id\n   OR NEW.started_at <> OLD.started_at\n   OR NEW.ended_at   IS NOT OLD.ended_at\n   OR NEW.note       <> OLD.note\n   OR NEW.source     <> OLD.source)\nBEGIN\n  SELECT RAISE(ABORT, 'time_entry_locked');\nEND;\n\nCREATE TRIGGER trg_time_entry_no_delete_exported\nBEFORE DELETE ON time_entry\nWHEN OLD.export_status = 'exported'\nBEGIN\n  SELECT RAISE(ABORT, 'time_entry_locked');\nEND;\n\nPRAGMA legacy_alter_table = OFF;\n\nPRAGMA foreign_keys = ON;\n",
  "0006_not_billed_audit_event.up.sql": "-- Takt — Migration 0006 \"not_billed_audit_event\", Vorwärtsrichtung\n-- takt: foreign_keys=off\n-- Deckt: E-047 (ersetzt E-037), R-10. Auflage aus T-022 (offene Frage 1).\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- ---------------------------------------------------------------------------\n-- Warum diese Migration ohne Fremdschlüsselprüfung läuft\n-- ---------------------------------------------------------------------------\n--\n-- Beide Teile bauen eine Tabelle um, und SQLite kennt kein ALTER TABLE für\n-- einen CHECK. Der vorgeschriebene Weg — neue Tabelle, kopieren, alte weg,\n-- umbenennen — stößt bei `time_entry` auf zwei Sperren, die beide an der\n-- eingeschalteten Fremdschlüsselprüfung hängen:\n--\n--   1. `export_audit` und `export_run_entry` verweisen mit ON DELETE RESTRICT\n--      auf `time_entry`. Das DROP führt eine stille Löschung aller Zeilen aus\n--      und scheitert an eben diesem RESTRICT.\n--   2. Ein RENAME zieht bei eingeschalteter Prüfung die REFERENCES-Klauseln\n--      der Kinder mit. Die Kinder zeigten danach auf die weggeworfene Tabelle.\n--\n-- Deshalb die Marke `-- takt: foreign_keys=off` in Zeile 2. Sie schaltet die\n-- Prüfung **nicht** ab, sie verschiebt sie: Der Läufer führt nach dem letzten\n-- Befehl dieser Datei und vor dem Festschreiben `PRAGMA foreign_key_check`\n-- über den ganzen Bestand aus und nimmt alles zurück, sobald ein Verweis ins\n-- Leere zeigt.\n--\n-- `legacy_alter_table` kommt dazu, weil ein RENAME sonst auch die Sicht\n-- `v_export_candidate` und die Trigger anderer Tabellen umschreibt — und weil\n-- er in seiner neueren Form das gesamte Schema neu einliest und dabei über die\n-- für einen Augenblick fehlende Tabelle stolpert.\n--\n-- ---------------------------------------------------------------------------\n-- Warum das Protokoll einen dritten Ereignistyp bekommt\n-- ---------------------------------------------------------------------------\n--\n-- E-047: „Nicht abrechnen\" ist kein Export. Der Exportstatus der Buchung geht\n-- trotzdem auf 'exported' — zweiwertig bleibt zweiwertig (E-032) —, aber das\n-- Protokoll muss festhalten, was tatsächlich geschah. Sonst beantwortet es die\n-- eine Frage nicht mehr, für die man ein Exportprotokoll führt: Wie viel Zeit\n-- ist nie abgerechnet worden?\n--\n-- Der CHECK aus 0001 verlangt für event='exported' einen Exportlauf **und** eine\n-- Exportzeile. Genau richtig: Eine als abgerechnet geführte Buchung ohne Beleg\n-- wäre der Fehler, den dieser CHECK verhindert. Deshalb wird er hier nicht\n-- gelockert, sondern um einen dritten, gleich strengen Zweig erweitert:\n--\n--   exported    Lauf und Zeile gesetzt,   Ziel 'exported'\n--   reset       Lauf und Zeile NULL,      Ziel 'open'\n--   not_billed  Lauf und Zeile NULL,      Ziel 'exported'\n--\n-- 'not_billed' ist damit an seiner Belegfreiheit erkennbar und nicht nur am\n-- Namen: Eine Zeile mit export_run_id kann kein 'not_billed' sein und\n-- umgekehrt. Eine Auswertung „nie abgerechnete Zeit\" ist ein WHERE auf event.\n--\n-- ---------------------------------------------------------------------------\n-- Warum ein Tabellenumbau\n-- ---------------------------------------------------------------------------\n--\n-- Der Umbau folgt dem vorgeschriebenen Weg: neue Tabelle, Inhalt kopieren,\n-- alte weg, umbenennen, Indizes und Trigger wortgleich wieder anlegen. Er ist\n-- verlustfrei — jede vorhandene Protokollzeile erfüllt den neuen CHECK, weil er\n-- die beiden alten Zweige unverändert enthält.\n--\n-- Die beiden Trigger verbieten UPDATE und DELETE auf dem Protokoll. Sie hängen\n-- an der alten Tabelle und verschwinden mit ihr; DROP TABLE löst kein\n-- BEFORE DELETE aus. Sie werden unten wortgleich wiederhergestellt. Zwischen\n-- DROP und CREATE liegt keine Zeile ungeschützt: Alles hier läuft in der einen\n-- Transaktion des Läufers.\n-- ---------------------------------------------------------------------------\n\n-- Die beiden folgenden Zeilen sind kein Widerspruch zur Marke in Zeile 2,\n-- sondern ihre Ergänzung: `PRAGMA foreign_keys` ist **innerhalb** einer\n-- offenen Transaktion wirkungslos. Läuft diese Datei über den Migrationsläufer,\n-- ist die Prüfung durch die Marke bereits vor BEGIN abgeschaltet und diese Zeile\n-- tut nichts. Wird sie ohne Läufer eingespielt — so machen es die Prüfpfade, die\n-- das Schema selbst untersuchen —, gibt es keine offene Transaktion, und dann\n-- ist genau diese Zeile die wirksame. Ohne sie zöge das RENAME weiter unten die\n-- REFERENCES-Klauseln der Kindtabellen mit auf die weggeworfene Tabelle.\nPRAGMA foreign_keys = OFF;\n\nPRAGMA legacy_alter_table = ON;\n\nCREATE TABLE export_audit_neu (\n  id                  TEXT NOT NULL PRIMARY KEY,\n  time_entry_id       TEXT NOT NULL REFERENCES time_entry       (id) ON DELETE RESTRICT,\n  event               TEXT NOT NULL CHECK (event           IN ('exported', 'reset', 'not_billed')),\n  previous_status     TEXT NOT NULL CHECK (previous_status IN ('open', 'exported')),\n  new_status          TEXT NOT NULL CHECK (new_status      IN ('open', 'exported')),\n  export_run_id       TEXT          REFERENCES export_run       (id) ON DELETE RESTRICT,\n  export_run_group_id TEXT          REFERENCES export_run_group (id) ON DELETE RESTRICT,\n  actor               TEXT NOT NULL,\n  reason              TEXT NOT NULL DEFAULT '',\n  occurred_at         TEXT NOT NULL,\n  CHECK (previous_status <> new_status),\n  CHECK ((event = 'exported'   AND export_run_id       IS NOT NULL\n                               AND export_run_group_id IS NOT NULL\n                               AND new_status = 'exported')\n      OR (event = 'reset'      AND export_run_id       IS NULL\n                               AND export_run_group_id IS NULL\n                               AND new_status = 'open')\n      OR (event = 'not_billed' AND export_run_id       IS NULL\n                               AND export_run_group_id IS NULL\n                               AND new_status = 'exported'))\n);\n\nINSERT INTO export_audit_neu\n  (id, time_entry_id, event, previous_status, new_status,\n   export_run_id, export_run_group_id, actor, reason, occurred_at)\nSELECT\n   id, time_entry_id, event, previous_status, new_status,\n   export_run_id, export_run_group_id, actor, reason, occurred_at\n  FROM export_audit;\n\nDROP TABLE export_audit;\n\nALTER TABLE export_audit_neu RENAME TO export_audit;\n\nCREATE INDEX ix_export_audit_entry ON export_audit (time_entry_id, occurred_at DESC);\nCREATE INDEX ix_export_audit_time  ON export_audit (occurred_at DESC);\n\nCREATE TRIGGER trg_export_audit_no_update BEFORE UPDATE ON export_audit\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\nCREATE TRIGGER trg_export_audit_no_delete BEFORE DELETE ON export_audit\nBEGIN SELECT RAISE(ABORT, 'append_only'); END;\n\n-- ---------------------------------------------------------------------------\n-- Zweiter Teil: die Buchung selbst darf ausgebucht sein\n-- ---------------------------------------------------------------------------\n--\n-- 0001 führt den CHECK `export_status = 'open' OR export_count >= 1` mit der\n-- Begründung „Exportiert und nie in einem Lauf gewesen ist widersprüchlich\"\n-- (datenmodell.md 4.4). Mit E-047 ist der Satz nicht mehr wahr: Eine\n-- ausgebuchte Buchung ist genau das — exportiert im Status, nie in einem Lauf.\n-- `export_count` mitzuzählen wäre der bequeme Ausweg und eine Falschaussage:\n-- Die Oberfläche liest `export_status = 'open' AND export_count > 0` als „schon\n-- einmal exportiert\" (R-10) und würde nach einem Zurücksetzen vor einer zweiten\n-- Abrechnung warnen, die nie eine erste hatte.\n--\n-- Der CHECK entfällt deshalb — aber die Zusage dahinter bleibt, und zwar\n-- schärfer als vorher. Statt „irgendein Zähler ist positiv\" verlangt der neue\n-- Trigger eine **Herkunft**: Wer eine offene Buchung auf `exported` setzt, ohne\n-- dass ein Exportlauf mitzählt, muss die Protokollzeile bereits geschrieben\n-- haben. Damit ist „beides oder keines\" (R-10) nicht mehr nur eine Zusage des\n-- Adapters, sondern eine des Schemas.\n--\n-- Zum Verfahren siehe den Dateikopf.\n\nALTER TABLE time_entry RENAME TO time_entry_alt;\n\nCREATE TABLE time_entry (\n  id               TEXT    NOT NULL PRIMARY KEY,\n  todo_id          TEXT    NOT NULL REFERENCES todo (id) ON DELETE RESTRICT,\n  started_at       TEXT    NOT NULL,\n  ended_at         TEXT,\n  duration_seconds INTEGER GENERATED ALWAYS AS (\n                     CASE WHEN ended_at IS NULL THEN NULL\n                          ELSE unixepoch(ended_at) - unixepoch(started_at) END\n                   ) STORED,\n  note             TEXT    NOT NULL DEFAULT '',\n  export_status    TEXT    NOT NULL DEFAULT 'open'  CHECK (export_status IN ('open', 'exported')),\n  export_count     INTEGER NOT NULL DEFAULT 0       CHECK (export_count >= 0),\n  source           TEXT    NOT NULL DEFAULT 'timer' CHECK (source IN ('timer', 'manual')),\n  created_at       TEXT    NOT NULL,\n  updated_at       TEXT    NOT NULL,\n  CHECK (started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z'),\n  CHECK (ended_at IS NULL OR ended_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]Z'),\n  CHECK (ended_at IS NULL OR ended_at > started_at),\n  CHECK (duration_seconds IS NULL OR duration_seconds >= 1),   -- E-008: Dauer 0 gibt es nicht\n  CHECK (export_status = 'open' OR ended_at IS NOT NULL)       -- laufend ist nie exportiert\n  -- Der Zähler-CHECK aus 0001 ist entfallen; an seiner Stelle steht\n  -- trg_time_entry_exported_needs_provenance weiter unten.\n);\n\nINSERT INTO time_entry\n  (id, todo_id, started_at, ended_at, note, export_status, export_count, source, created_at, updated_at)\nSELECT\n   id, todo_id, started_at, ended_at, note, export_status, export_count, source, created_at, updated_at\n  FROM time_entry_alt;\n\nDROP TABLE time_entry_alt;\n\n-- Indizes und Trigger wortgleich aus 0001.\nCREATE UNIQUE INDEX ux_time_entry_running ON time_entry ((1)) WHERE ended_at IS NULL;\nCREATE INDEX ix_time_entry_todo   ON time_entry (todo_id, started_at DESC);\nCREATE INDEX ix_time_entry_queue  ON time_entry (todo_id, started_at) WHERE export_status = 'open';\nCREATE INDEX ix_time_entry_day    ON time_entry (started_at DESC);\nCREATE INDEX ix_time_entry_reset  ON time_entry (todo_id) WHERE export_status = 'open' AND export_count > 0;\n\nCREATE TRIGGER trg_time_entry_locked\nBEFORE UPDATE ON time_entry\nWHEN OLD.export_status = 'exported' AND NEW.export_status = 'exported'\n AND (NEW.todo_id    <> OLD.todo_id\n   OR NEW.started_at <> OLD.started_at\n   OR NEW.ended_at   IS NOT OLD.ended_at\n   OR NEW.note       <> OLD.note\n   OR NEW.source     <> OLD.source)\nBEGIN\n  SELECT RAISE(ABORT, 'time_entry_locked');\nEND;\n\nCREATE TRIGGER trg_time_entry_no_delete_exported\nBEFORE DELETE ON time_entry\nWHEN OLD.export_status = 'exported'\nBEGIN\n  SELECT RAISE(ABORT, 'time_entry_locked');\nEND;\n\n-- Neu: kein Exportstatus ohne Herkunft.\n--\n-- Zählt ein Exportlauf mit, steigt `export_count` in derselben Anweisung — die\n-- Bedingung greift dann nicht. Bleibt der Zähler stehen, ist es eine\n-- Ausbuchung, und dann **muss** die Protokollzeile schon dastehen: Der Adapter\n-- schreibt sie vor dem Statuswechsel (`markNotBilled` in repo-export.ts).\n--\n-- Geprüft wird die **jüngste** Zeile des Protokolls, nicht irgendeine. Eine\n-- alte Ausbuchung, die längst zurückgesetzt wurde, rechtfertigt keine neue:\n-- Nach einem Zurücksetzen ist die jüngste Zeile 'reset', und der Versuch\n-- scheitert.\n--\n-- `IS NOT` statt `<>`: Ohne jede Protokollzeile liefert die Unterabfrage NULL,\n-- und ein Vergleich mit `<>` wäre dann NULL statt wahr — die Prüfung liefe ins\n-- Leere, ausgerechnet im Fall „gar nichts protokolliert\".\nCREATE TRIGGER trg_time_entry_exported_needs_provenance\nBEFORE UPDATE ON time_entry\nWHEN OLD.export_status = 'open' AND NEW.export_status = 'exported'\n AND NEW.export_count = OLD.export_count\n AND (SELECT event FROM export_audit\n       WHERE time_entry_id = NEW.id\n       ORDER BY occurred_at DESC, id DESC\n       LIMIT 1) IS NOT 'not_billed'\nBEGIN\n  SELECT RAISE(ABORT, 'export_status_not_settable');\nEND;\n\nPRAGMA legacy_alter_table = OFF;\n\nPRAGMA foreign_keys = ON;\n",
  "0007_audit_order_by_rowid.down.sql": "-- Takt — Migration 0007 \"audit_order_by_rowid\", Rückwärtsrichtung\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- Stellt `trg_time_entry_exported_needs_provenance` im Wortlaut aus Migration\n-- 0006 wieder her: `ORDER BY occurred_at DESC, id DESC`.\n--\n-- Verlustfrei. Es wird keine Zeile angefasst; zurück kommt allein der\n-- Wettlauf, den 0007 beseitigt hat — zwei Protokollzeilen derselben Buchung in\n-- derselben Sekunde ordnet der Trigger danach wieder über die Kennung, und\n-- damit über den Zufall in den unteren Bits einer UUIDv7.\n--\n-- Die Begründung steht vollständig im Kopf der Vorwärtsdatei. Sie wird hier\n-- nicht wiederholt, damit es nur eine Fassung davon gibt.\n\nDROP TRIGGER IF EXISTS trg_time_entry_exported_needs_provenance;\n\nCREATE TRIGGER trg_time_entry_exported_needs_provenance\nBEFORE UPDATE ON time_entry\nWHEN OLD.export_status = 'open' AND NEW.export_status = 'exported'\n AND NEW.export_count = OLD.export_count\n AND (SELECT event FROM export_audit\n       WHERE time_entry_id = NEW.id\n       ORDER BY occurred_at DESC, id DESC\n       LIMIT 1) IS NOT 'not_billed'\nBEGIN\n  SELECT RAISE(ABORT, 'export_status_not_settable');\nEND;\n",
  "0007_audit_order_by_rowid.up.sql": "-- Takt — Migration 0007 \"audit_order_by_rowid\", Vorwärtsrichtung\n-- Deckt: R-10, E-047. Auflage aus T-041 (Nachtrag), freigegeben in T-047.\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- ---------------------------------------------------------------------------\n-- Eine Integritätsprüfung der Datenbank darf nicht am Kennungsgenerator der\n-- Anwendung hängen\n-- ---------------------------------------------------------------------------\n--\n-- `trg_time_entry_exported_needs_provenance` aus Migration 0006 lässt den\n-- Wechsel auf `export_status = 'exported'` ohne mitzählenden Exportlauf nur zu,\n-- wenn die **jüngste** Protokollzeile der Buchung `not_billed` ist. „Jüngste\"\n-- war bisher `ORDER BY occurred_at DESC, id DESC`.\n--\n-- `occurred_at` ist sekundengenau. Zwei Protokollzeilen derselben Buchung in\n-- derselben Sekunde — ein Zurücksetzen und eine sofortige Ausbuchung, wie sie\n-- die Oberfläche mit zwei Klicks erzeugt — sind über `occurred_at` allein nicht\n-- zu ordnen. Dann entscheidet der Zweitschlüssel, und der war die Kennung.\n--\n-- Die Kennung ist eine UUIDv7. Sie ist millisekundengenau **sortierbar**, aber\n-- innerhalb derselben Millisekunde füllt der Zufall die restlichen Bits: Zwei\n-- in derselben Millisekunde erzeugte Kennungen stehen mit gleicher\n-- Wahrscheinlichkeit in der einen wie in der anderen Reihenfolge. Der Trigger\n-- las also in einem von zwei Fällen die **falsche** Zeile als „jüngste\" — und\n-- ließ einen Statuswechsel zu, den er verbieten sollte, oder verbot einen, den\n-- er zulassen sollte. T-041 hat das gemessen: neun Abweichungen in vierzig\n-- Runden, in drei von vier Läufen unsichtbar.\n--\n-- `ids.ts` hat seither einen Zähler (RFC 9562 6.2), der die Ordnung auch\n-- innerhalb einer Millisekunde herstellt. Das behebt die Ursache breit — es\n-- lässt die Zusage der Datenbank aber an einer Zusage der Anwendung hängen.\n-- Wer `IdSource` austauscht, hebt eine Integritätsprüfung auf, ohne davon zu\n-- erfahren. Diese Migration hängt sie stattdessen an etwas, das die Datenbank\n-- selbst weiß.\n--\n-- ---------------------------------------------------------------------------\n-- Warum `rowid` die Reihenfolge kennt\n-- ---------------------------------------------------------------------------\n--\n-- `export_audit` ist eine gewöhnliche Rowid-Tabelle: `id` ist TEXT und damit\n-- kein `INTEGER PRIMARY KEY`, also führt SQLite den verborgenen `rowid` selbst.\n-- Ohne AUTOINCREMENT vergibt er `max(rowid) + 1` — die Wiederverwendung einer\n-- Nummer setzte voraus, dass die höchste Zeile gelöscht wird, und das verbieten\n-- `trg_export_audit_no_update` und `trg_export_audit_no_delete`. Die Tabelle\n-- ist anhängend; `rowid` ist damit streng aufsteigend in der\n-- Einfügereihenfolge und der einzige Wert in dieser Tabelle, der die\n-- Reihenfolge **kennt**, statt sie aus einer Uhr oder einem Zufall zu schätzen.\n--\n-- Zur Vollständigkeit: Ein `VACUUM` darf `rowid` einer Tabelle ohne explizites\n-- `INTEGER PRIMARY KEY` neu vergeben. Es tut das in der bestehenden Ordnung,\n-- die Reihenfolge bleibt also erhalten — und der Läufer benutzt ohnehin nur\n-- `VACUUM INTO`, das eine **Kopie** schreibt und den laufenden Bestand nicht\n-- anfasst.\n--\n-- ---------------------------------------------------------------------------\n-- Verlustfrei\n-- ---------------------------------------------------------------------------\n--\n-- Es wird keine Zeile angefasst und keine Tabelle umgebaut, nur eine Bedingung\n-- getauscht. Die Rückwärtsrichtung stellt den Wortlaut aus 0006 wieder her und\n-- ist ebenso verlustfrei — sie holt den Wettlauf zurück, mehr nicht.\n\nDROP TRIGGER IF EXISTS trg_time_entry_exported_needs_provenance;\n\nCREATE TRIGGER trg_time_entry_exported_needs_provenance\nBEFORE UPDATE ON time_entry\nWHEN OLD.export_status = 'open' AND NEW.export_status = 'exported'\n AND NEW.export_count = OLD.export_count\n AND (SELECT event FROM export_audit\n       WHERE time_entry_id = NEW.id\n       ORDER BY occurred_at DESC, rowid DESC\n       LIMIT 1) IS NOT 'not_billed'\nBEGIN\n  SELECT RAISE(ABORT, 'export_status_not_settable');\nEND;\n",
  "0008_tag_name_key.down.sql": "-- Takt — Migration 0008 \"tag_name_key\", Rückwärtsrichtung\n--\n-- Die Reihenfolge ist keine Formsache: SQLite verweigert `DROP COLUMN` für eine\n-- Spalte, die in einem Index oder einem Trigger vorkommt. Erst die Trigger,\n-- dann die Indizes, dann die Spalte.\n--\n-- **Was der Rückweg nicht zurücknimmt.** Die Vorwärtsrichtung hat den Leerraum\n-- in `tag.name` vereinheitlicht und bestehende Doppelte mit „ (2)“ auseinander-\n-- gezogen. Beides bleibt stehen. Der ursprüngliche Text ist nach dem UPDATE\n-- nirgends mehr gespeichert; eine Rückwärtsmigration, die ihn erriete, wäre\n-- schlimmer als eine, die ihn stehen lässt. Der Rückweg auf einem benutzten\n-- Bestand ist die Sicherungskopie, die der Migrationsläufer vor jedem Lauf\n-- anlegt (datenmodell.md 8).\n--\n-- Nach dem Rückweg gilt wieder allein `ux_tag_name` aus 0001: Namen sind je\n-- Ordner eindeutig, aber nur unter ASCII-Groß- und -Kleinschreibung.\n\nDROP TRIGGER IF EXISTS trg_tag_name_key_insert;\nDROP TRIGGER IF EXISTS trg_tag_name_key_update;\n\nDROP INDEX IF EXISTS ux_tag_name_key;\nDROP INDEX IF EXISTS ix_tag_name_key;\n\nALTER TABLE tag DROP COLUMN name_key;\n",
  "0008_tag_name_key.up.sql": "-- Takt — Migration 0008 \"tag_name_key\", Vorwärtsrichtung\n-- Deckt: A-4.1, A-4.5, T-058\n--\n-- ===========================================================================\n-- Wogegen\n-- ===========================================================================\n--\n-- Beim Anlegen eines Todos darf ein neuer Tagname mit angegeben werden. Zwei\n-- Fenster, die gleichzeitig ein Todo mit demselben neuen Tag anlegen, dürfen\n-- kein zweites Tag erzeugen. Das ist eine Zusage über einen Wettlauf, und eine\n-- solche Zusage hält nur, wenn die **Datenbank** sie hält — eine Prüfung im\n-- Adapter ist immer nur so gut wie der Abstand zwischen ihr und dem INSERT.\n--\n-- Bis hierher gab es `ux_tag_name ON tag (COALESCE(folder_id,'~root'), name\n-- COLLATE NOCASE)`. Der Index deckt A–Z und sonst nichts:\n--\n--   „Backend“ gegen „backend“   → abgewiesen        ✔ (NOCASE)\n--   „ backend“ gegen „backend“  → beide angelegt    ✘ Leerzeichen\n--   „Änderung“ gegen „änderung“ → beide angelegt    ✘ NOCASE kennt kein Ä\n--   „back  end“ gegen „back end“→ beide angelegt    ✘ doppelter Leerraum\n--\n-- Diese Migration führt die Spalte `tag.name_key` ein: den Vergleichsschlüssel\n-- aus `packages/domain/src/tag-name.ts`. Er trägt den eindeutigen Index, und\n-- damit ist „kein doppeltes Tag“ eine Zusage des Schemas.\n--\n-- ===========================================================================\n-- Warum der Schlüssel hier Zeichen für Zeichen nachgebaut wird\n-- ===========================================================================\n--\n-- SQLite hat keine Unicode-Faltung: `lower()` fasst A–Z an und sonst nichts.\n-- Ein Rückgriff darauf ergäbe zwei Regeln — eine in der Domäne, eine in der\n-- Datenbank — und die Datenbank erzwänge die schwächere. Genau dort entstünde\n-- das doppelte Tag, das der Index verhindern soll.\n--\n-- Deshalb bildet die rekursive Abfrage unten die **aufgezählte** Faltung aus\n-- tag-name.ts nach: ASCII A–Z, der lateinische Ergänzungsblock U+00C0–U+00DE\n-- ohne das Malzeichen U+00D7, das große ẞ (U+1E9E) auf ß, jeder Leerraum zu\n-- einem Leerzeichen, Folgen zu einem, vorn und hinten nichts.\n-- `pnpm --filter @takt/local-api proof:tags` hält beide Fassungen gegeneinander\n-- und wird rot, sobald eine von ihnen sich bewegt.\n--\n-- **Was diese Migration nicht kann:** Unicode-Zusammensetzung (NFC). Ein\n-- bestehender Name, in dem „ä“ als „a“ plus Trema gespeichert ist, bekommt\n-- einen Schlüssel in derselben Zerlegung. Die Domäne setzt NFC voraus; jeder\n-- neu angelegte oder umbenannte Tagname geht durch sie hindurch. Für Namen, die\n-- über eine Tastatur unter Windows oder Linux entstanden sind, ist der Fall\n-- gegenstandslos.\n--\n-- ===========================================================================\n-- Bestehende Doppelte\n-- ===========================================================================\n--\n-- Ein Bestand kann heute „ backend“ und „backend“ nebeneinander führen; unter\n-- dem neuen Schlüssel sind das zwei gleiche. Der Index ließe sich dann nicht\n-- anlegen und die Migration bräche ab. Statt abzubrechen bekommt jedes weitere\n-- Tag mit demselben Schlüssel ein „ (2)“, „ (3)“ … an den Namen — sichtbar,\n-- verlustfrei und vom Benutzer nachträglich zu bereinigen. Die Reihenfolge ist\n-- die der Anlage; das zuerst angelegte Tag behält seinen Namen.\n--\n-- Zusammenführen wäre die Alternative gewesen und ist die schlechtere: Sie\n-- verschöbe Todos zwischen Tags und damit zwischen Pools, ohne dass jemand\n-- gefragt worden wäre.\n\n-- ---------------------------------------------------------------------------\n-- 1. Die Spalte\n-- ---------------------------------------------------------------------------\n--\n-- `DEFAULT ''` ist der Preis dafür, dass SQLite eine NOT-NULL-Spalte nur mit\n-- Vorgabewert anhängen lässt. Der leere Schlüssel wird deshalb unten von einem\n-- Trigger abgewiesen — sonst wäre die Vorgabe ein stiller Ausweg für einen\n-- INSERT, der die Spalte vergisst.\nALTER TABLE tag ADD COLUMN name_key TEXT NOT NULL DEFAULT '';\n\n-- ---------------------------------------------------------------------------\n-- 2. Anzeigeform und Schlüssel für den Bestand\n-- ---------------------------------------------------------------------------\n--\n-- Ein Durchlauf je Zeichen. `norm` sammelt die Anzeigeform (Leerraum\n-- vereinheitlicht), `folded` denselben Text zusätzlich gefaltet. Beide\n-- entstehen im selben Durchlauf, damit sie nicht auseinanderlaufen können.\n--\n-- Die Obergrenze `i <= 1000` ist der Notausgang für einen Namen, den ein\n-- Eingriff von Hand länger gemacht hat, als der CHECK je zugelassen hätte.\nCREATE TEMP TABLE _tag_key AS\nWITH RECURSIVE walk(id, src, i, norm, folded) AS (\n  SELECT id, name, 1, '', '' FROM tag\n  UNION ALL\n  SELECT\n    id,\n    src,\n    i + 1,\n    CASE\n      WHEN unicode(substr(src, i, 1)) IN (9,10,11,12,13,32,160,5760,8232,8233,8239,8287,12288,65279)\n        OR unicode(substr(src, i, 1)) BETWEEN 8192 AND 8202\n      THEN CASE WHEN norm = '' OR substr(norm, -1, 1) = ' ' THEN norm ELSE norm || ' ' END\n      ELSE norm || substr(src, i, 1)\n    END,\n    CASE\n      WHEN unicode(substr(src, i, 1)) IN (9,10,11,12,13,32,160,5760,8232,8233,8239,8287,12288,65279)\n        OR unicode(substr(src, i, 1)) BETWEEN 8192 AND 8202\n      THEN CASE WHEN folded = '' OR substr(folded, -1, 1) = ' ' THEN folded ELSE folded || ' ' END\n      WHEN unicode(substr(src, i, 1)) BETWEEN 65 AND 90\n      THEN folded || char(unicode(substr(src, i, 1)) + 32)\n      WHEN unicode(substr(src, i, 1)) BETWEEN 192 AND 222\n       AND unicode(substr(src, i, 1)) <> 215\n      THEN folded || char(unicode(substr(src, i, 1)) + 32)\n      WHEN unicode(substr(src, i, 1)) = 7838\n      THEN folded || char(223)\n      ELSE folded || substr(src, i, 1)\n    END\n  FROM walk\n  WHERE i <= length(src) AND i <= 1000\n),\n-- Die letzte Zeile je Tag trägt das vollständige Ergebnis.\nfolded_tag(id, norm, folded) AS (\n  SELECT id, rtrim(norm, ' '), rtrim(folded, ' ')\n    FROM walk\n   WHERE i = length(src) + 1\n)\n-- `rn` zählt, das wievielte Tag mit **diesem** Schlüssel in **diesem** Ordner\n-- das ist. Alles über 1 ist ein bestehendes Doppeltes; siehe Schritt 3.\nSELECT\n  f.id     AS id,\n  f.norm   AS norm,\n  f.folded AS folded,\n  ROW_NUMBER() OVER (PARTITION BY COALESCE(t.folder_id, '~root'), f.folded\n                     ORDER BY t.created_at, t.id) AS rn\nFROM folded_tag f JOIN tag t ON t.id = f.id;\n\n-- ---------------------------------------------------------------------------\n-- 3. Bestehende Doppelte auseinanderziehen\n-- ---------------------------------------------------------------------------\n--\n-- Je Ordner, weil der eindeutige Index je Ordner gilt: Dasselbe Tag darf in\n-- zwei Ordnern stehen (A-4.2).\n--\n-- Der Zusatz geht auf **beide** Spalten. `folded` bleibt damit die Faltung von\n-- `norm`: Ziffern, Klammern und Leerzeichen falten auf sich selbst.\nUPDATE _tag_key\n   SET norm   = norm   || ' (' || rn || ')',\n       folded = folded || ' (' || rn || ')'\n WHERE rn > 1;\n\n-- ---------------------------------------------------------------------------\n-- 4. Übertragen — in zwei Durchläufen, und das ist der Punkt\n-- ---------------------------------------------------------------------------\n--\n-- `ux_tag_name` aus 0001 wird **je Zeile** geprüft, nicht am Ende der\n-- Anweisung. Aus „back  end“ wird „back end“, und solange die Zeile daneben\n-- noch „back end“ heißt, stünden für die Dauer eines Schreibvorgangs zwei\n-- gleiche Namen da — die Migration bräche mit einer UNIQUE-Verletzung ab,\n-- obwohl das Ergebnis eindeutig gewesen wäre. Gemessen, nicht befürchtet.\n--\n-- Deshalb erst auf einen Zwischenwert, der nicht kollidieren kann, und dann auf\n-- den endgültigen. Dasselbe Muster wie beim Umsortieren der Kanban-Spalten\n-- (`repo-statuses.ts`), aus demselben Grund.\nUPDATE tag SET name = '~takt-0008~' || id;\n\n-- `updated_at` bleibt stehen. Eine Vereinheitlichung des Leerraums ist keine\n-- Änderung des Benutzers, und ein aufgefrischter Zeitstempel schöbe jedes Tag\n-- in jeder nach Änderung sortierten Liste nach oben.\nUPDATE tag\n   SET name     = (SELECT norm   FROM _tag_key WHERE _tag_key.id = tag.id),\n       name_key = (SELECT folded FROM _tag_key WHERE _tag_key.id = tag.id)\n WHERE EXISTS (SELECT 1 FROM _tag_key WHERE _tag_key.id = tag.id);\n\nDROP TABLE _tag_key;\n\n-- ---------------------------------------------------------------------------\n-- 5. Die Zusage\n-- ---------------------------------------------------------------------------\n--\n-- `ux_tag_name_key` ist der Wettlaufschutz: Zwei gleichzeitige Anlagen mit\n-- demselben Schlüssel können nicht beide gelingen, gleich wie die Anwendung\n-- vorher geprüft hat. `ux_tag_name` aus 0001 bleibt daneben stehen — er ist\n-- schwächer, aber nicht falsch, und er trägt die Fehlermeldung „In diesem\n-- Ordner gibt es bereits ein Tag mit diesem Namen“, auf die `errors.ts` bereits\n-- abbildet.\nCREATE UNIQUE INDEX ux_tag_name_key ON tag (COALESCE(folder_id, '~root'), name_key);\n\n-- Der **ordnerübergreifende** Zugriff: „Gibt es irgendwo ein Tag namens\n-- backend?“ Ohne diesen Index wäre das ein Tabellendurchlauf bei jedem\n-- Anlegen eines Todos mit neuem Tag.\nCREATE INDEX ix_tag_name_key ON tag (name_key);\n\n-- ---------------------------------------------------------------------------\n-- 6. Der Schlüssel darf nicht leer und nicht ungefaltet sein\n-- ---------------------------------------------------------------------------\n--\n-- Ein CHECK wäre der richtige Ort, aber SQLite kann keinen an eine bestehende\n-- Tabelle anhängen, ohne sie neu zu bauen — und ein Neubau von `tag` risse drei\n-- Fremdschlüssel mit. Der Trigger leistet dasselbe.\n--\n-- Was er prüfen kann und was nicht: Ob der Schlüssel wirklich zu **diesem**\n-- Namen gehört, weiß nur die Faltung, und die steht in TypeScript. Prüfbar ist\n-- dagegen, ob der Wert überhaupt wie ein Schlüssel aussieht — nicht leer, keine\n-- Großbuchstaben, kein Leerraum am Rand, keine doppelten Leerzeichen. Das\n-- trifft den wahrscheinlichsten Fehlgriff: `name_key` mit dem Namen zu belegen.\nCREATE TRIGGER trg_tag_name_key_insert\nBEFORE INSERT ON tag\nWHEN NEW.name_key = ''\n  OR NEW.name_key <> lower(NEW.name_key)\n  OR NEW.name_key <> trim(NEW.name_key)\n  OR instr(NEW.name_key, '  ') > 0\nBEGIN SELECT RAISE(ABORT, 'tag_name_key_invalid'); END;\n\nCREATE TRIGGER trg_tag_name_key_update\nBEFORE UPDATE ON tag\nWHEN NEW.name_key = ''\n  OR NEW.name_key <> lower(NEW.name_key)\n  OR NEW.name_key <> trim(NEW.name_key)\n  OR instr(NEW.name_key, '  ') > 0\nBEGIN SELECT RAISE(ABORT, 'tag_name_key_invalid'); END;\n",
  "0009_pool_placement.down.sql": "-- Takt — Migration 0009 \"pool_placement\", Rückwärtsrichtung\n--\n-- Ein Schritt, weil die Vorwärtsrichtung einer war. Kein Index und kein Trigger\n-- hängt an der Spalte — der Grund dafür steht in der Vorwärtsdatei, Abschnitt 2\n-- —, deshalb nimmt SQLite das DROP COLUMN ohne Vorarbeit an.\n--\n-- **Was der Rückweg nicht zurücknimmt.** Welche Regel eine Kanban-Spalte war,\n-- steht danach nirgends mehr. Nach dem Rückweg ist jede Regel wieder ein Pool\n-- und erscheint in der Pool-Liste — auch die, die der Benutzer ausdrücklich nur\n-- auf dem Board haben wollte. Nichts geht dabei verloren außer dieser\n-- Zuordnung: Name, Regel und Position stehen unverändert da.\n--\n-- Das ist die richtige Richtung des Verlusts. Die Alternative wäre, Regeln mit\n-- `placement = 'board'` beim Rückweg zu löschen, weil sie „vorher nicht\n-- existierten\" — das nähme dem Benutzer eine von Hand eingerichtete Regel weg,\n-- ohne zu fragen. Der eigentliche Rückweg auf einem benutzten Bestand ist\n-- ohnehin die Sicherungskopie, die der Migrationsläufer vor jedem Lauf anlegt\n-- (datenmodell.md 8).\n\nALTER TABLE pool DROP COLUMN placement;\n",
  "0009_pool_placement.up.sql": "-- Takt — Migration 0009 \"pool_placement\", Vorwärtsrichtung\n-- Deckt: A-3.*, A-5.3, A-5.4, E-054\n--\n-- ===========================================================================\n-- Wogegen\n-- ===========================================================================\n--\n-- Bis hierher war `todo_status` zweierlei zugleich: die Eigenschaft am Todo und\n-- die Spalte auf dem Kanban-Board. Der Auftraggeber hat das getrennt (E-054):\n--\n--   „Die Statusspalte ist nicht gleichbedeutend mit einem Kanban-Board. Ein\n--    Kanban-Board kann aus einer oder mehreren frei konfigurierbaren Spalten\n--    bestehen. Daher sollen die Kanban-Spalten unabhängig vom Status\n--    konfigurierbar sein.\"\n--\n-- Eine Kanban-Spalte ist seitdem eine **Regel über Tags**, wie ein Pool. Der\n-- Status bleibt, wo er war: `todo.status_id`, Tabelle `todo_status`, Migration\n-- 0002 mit ihren vier Startwerten, die Standardspalte für neue Todos. Diese\n-- Migration fasst davon nichts an.\n--\n-- ===========================================================================\n-- Warum keine Tabelle `board_column`\n-- ===========================================================================\n--\n-- Weil sie `pool` Wort für Wort abgeschrieben hätte: Name, Position,\n-- Regelterme, Auflösung über Ordner samt Unterordnern, „genau eine Quelle je\n-- Regel\", der eindeutige Name, die Mitgliederabfrage, die leere Regel, die\n-- nichts trifft. Das wäre die achte Doppelung dieses Bestands gewesen — und\n-- die teuerste, weil die rekursive Ordnerauflösung (datenmodell.md 4.4) und die\n-- Blätterung doppelt daran gehangen hätten.\n--\n-- Es gibt deshalb **eine** Entität und einen Unterschied: `pool.placement`\n-- sagt, auf welcher Fläche eine Regel erscheint.\n--\n--   'pool'  — nur in der Pool-Liste\n--   'board' — nur als Spalte des Kanban-Boards\n--   'both'  — beides, dieselbe Regel an zwei Stellen\n--\n-- Dreiwertig und nie leer, aus demselben Grund wie der Exportstatus. Zwei\n-- Wahrheitswerte nebeneinander hätten vier Zustände, und einer davon — beide\n-- falsch — wäre eine Regel, die nirgends erscheint und die niemand wiederfindet.\n--\n-- ===========================================================================\n-- Was mit dem Bestand geschieht: nichts, und das ist die Entscheidung\n-- ===========================================================================\n--\n-- Jede vorhandene Regel bekommt 'pool'. Sie steht danach genau dort, wo sie\n-- vorher stand, und **keine** wird zur Spalte.\n--\n-- Das Board ist damit nach der Aktualisierung leer, bis jemand eine Spalte\n-- einrichtet. Die beiden Alternativen wären schlechter gewesen:\n--\n--  - Alle vorhandenen Pools zu Spalten machen ('both'): Das Board wäre eine\n--    Kopie der Pool-Liste, die niemand bestellt hat, und der Benutzer müsste\n--    erst aufräumen, was ihm eingerichtet wurde.\n--  - Die vier Statuswerte in Spalten übersetzen: Es gibt keine Übersetzung.\n--    Eine Spalte ist eine Regel über **Tags**; „In Progress\" ist kein Tag. Der\n--    Auftraggeber hat ausdrücklich ausgeschlossen, dass Takt von sich aus Tags\n--    setzt („du darfst keine Tags setzen\"). Eine Migration, die dafür vier Tags\n--    anlegt und an jedes Todo hängt, täte genau das.\n--\n-- Ein leeres Board ist sichtbar leer. Ein Board, das mit erfundenen Spalten\n-- gefüllt wurde, sieht aus, als hätte es jemand so gewollt.\n\n-- ---------------------------------------------------------------------------\n-- 1. Die Spalte\n-- ---------------------------------------------------------------------------\n--\n-- `DEFAULT 'pool'` ist zweierlei: der Wert für den Bestand (SQLite füllt beim\n-- ALTER jede vorhandene Zeile damit) und die Vorgabe für jede künftige Zeile,\n-- die den Wert nicht nennt. Beides ist gewollt und dasselbe: Wer eine Regel\n-- anlegt, ohne eine Fläche zu nennen, legt einen Pool an.\n--\n-- Der CHECK ist an dieser Stelle zulässig — anders als PRIMARY KEY und UNIQUE,\n-- die ALTER TABLE ADD COLUMN nicht annimmt — und gemessen wirksam: ein INSERT\n-- mit 'quatsch' wird abgewiesen.\nALTER TABLE pool ADD COLUMN placement TEXT NOT NULL DEFAULT 'pool'\n  CHECK (placement IN ('pool', 'board', 'both'));\n\n-- ---------------------------------------------------------------------------\n-- 2. Kein Index — und warum das hier eine Aussage ist\n-- ---------------------------------------------------------------------------\n--\n-- Die beiden neuen Abfragen lauten `WHERE placement IN ('pool','both')` und\n-- `WHERE placement IN ('board','both')`, jeweils `ORDER BY position`. Ein\n-- partieller Index darauf wäre schnell hingeschrieben und wertlos: `pool` hält\n-- die Regeln, die ein Mensch von Hand eingerichtet hat — eine Handvoll Zeilen,\n-- in keinem denkbaren Bestand mehr als ein paar Dutzend. SQLite liest die\n-- Tabelle in einem Durchlauf, und `ux_pool_position` trägt die Ordnung bereits.\n--\n-- Ein Index hier behauptete einen Zugriffspfad, den kein Abfrageplan je\n-- wählen würde. Dieselbe Begründung steht bei `timer_heartbeat`\n-- (datenmodell.md 9), und sie gilt hier aus demselben Grund.\n",
  "0010_drop_board_rank.down.sql": "-- Takt — Migration 0010 \"drop_board_rank\", Rückwärtsrichtung\n--\n-- ===========================================================================\n-- Warum dieser Rückweg verlustfrei ist\n-- ===========================================================================\n--\n-- Der einzige Wert, der je in `board_rank` stand, war die Kennung des Todos\n-- selbst: `repo-todos.ts` hat ihn beim Anlegen aus `id` gesetzt, und kein\n-- Aufrufer hat ihn je überschrieben (T-066, gemessen). `UPDATE todo SET\n-- board_rank = id` stellt deshalb nicht irgendeinen brauchbaren Wert her,\n-- sondern **genau den**, der vor Migration 0010 dort stand.\n--\n-- Das ist der Unterschied zu 0009: Dort verliert der Rückweg eine Auskunft\n-- (welche Regel eine Kanban-Spalte war). Hier verliert er nichts.\n--\n-- ---------------------------------------------------------------------------\n-- 1. Die Spalte, mit Vorgabewert — und warum das kein Fehler ist\n-- ---------------------------------------------------------------------------\n--\n-- `0001_initial.up.sql` legt `board_rank TEXT NOT NULL` **ohne** Vorgabewert\n-- an. Hier steht `DEFAULT ''`, weil SQLite anders nicht kann: Eine Spalte, die\n-- über ALTER TABLE ADD COLUMN entsteht, darf NOT NULL nur zusammen mit einem\n-- Vorgabewert tragen — sonst hätten die vorhandenen Zeilen keinen Wert.\n--\n-- Der Unterschied ist nach Schritt 3 folgenlos, und das ist der Grund, warum\n-- er hier stehen bleiben darf: `ux_todo_rank` ist eindeutig über\n-- (status_id, board_rank). Ein INSERT, der `board_rank` ausließe, bekäme ''\n-- und liefe beim zweiten Mal in derselben Statusspalte in die\n-- Eindeutigkeitsbedingung. Die Wache überlebt den Rückweg, sie heißt nur\n-- anders: UNIQUE statt NOT NULL.\n--\n-- Die verlustfreie Alternative wäre ein vollständiger Tabellenneubau nach dem\n-- zwölfschrittigen Verfahren von SQLite. Er müsste `todo` samt vier CHECK-\n-- Bedingungen, vier weiteren Indizes und den Fremdschlüsseln aus `todo_note`,\n-- `todo_tag` und `time_entry` neu aufbauen — und damit das Wesentliche\n-- (die Kundendaten) für das Unwesentliche (ein fehlendes DEFAULT) aufs Spiel\n-- setzen. Der Rückweg ist Werkzeug für Entwicklung und für einen\n-- fehlgeschlagenen Aktualisierungslauf; die Rettung eines benutzten Bestands\n-- ist die Sicherungskopie, die der Läufer vorher anlegt (datenmodell.md 8).\nALTER TABLE todo ADD COLUMN board_rank TEXT NOT NULL DEFAULT '';\n\n-- ---------------------------------------------------------------------------\n-- 2. Der Wert, den die Spalte vorher trug\n-- ---------------------------------------------------------------------------\n--\n-- Vor Schritt 3, nicht danach: Mit '' in jeder Zeile verletzten schon zwei\n-- Todos in derselben Statusspalte die Eindeutigkeit von `ux_todo_rank`.\nUPDATE todo SET board_rank = id;\n\n-- ---------------------------------------------------------------------------\n-- 3. Die beiden Indizes aus 0001, Wort für Wort\n-- ---------------------------------------------------------------------------\nDROP INDEX ix_todo_status;\nCREATE INDEX ix_todo_status ON todo (status_id, board_rank);\nCREATE UNIQUE INDEX ux_todo_rank ON todo (status_id, board_rank);\n",
  "0010_drop_board_rank.up.sql": "-- Takt — Migration 0010 \"drop_board_rank\", Vorwärtsrichtung\n-- Deckt: A-5.2 (entfallen), A-13.6, E-054\n--\n-- ===========================================================================\n-- Wogegen\n-- ===========================================================================\n--\n-- `todo.board_rank` war der Sortierschlüssel innerhalb einer Kanban-Spalte, aus\n-- der Zeit, als das Board eine Gruppierung nach `status_id` war und Karten\n-- gezogen wurden (A-5.2, A-13.6). Mit E-054 ist beides entfallen: Eine\n-- Kanban-Spalte ist seitdem eine Regel über Tags, eine Karte kann in mehreren\n-- Spalten zugleich stehen, und es gibt keine Route, die eine Karte in eine\n-- Spalte legt.\n--\n-- Damit war die Spalte tot, und zwar **gemessen** und nicht vermutet (T-066):\n--\n--   * Kein Aufrufer hat sie je gesetzt. `TodoUpdate.boardRank` war die einzige\n--     schreibbare Stelle; weder die Oberfläche noch das Add-in noch ein\n--     Prüfpfad hat das Feld je geschickt (`proof:callers` liest jeden Rumpf der\n--     Oberfläche).\n--   * Der Wert eines neuen Todos war seine eigene Kennung (`repo-todos.ts`).\n--     Die Reihenfolge war damit die der Anlage und nie die eines Benutzers.\n--   * Sortiert wurde danach an genau einer Stelle, im alten Ziehen-Board.\n--\n-- Eine als tot beschriftete Spalte ist besser als eine unbeschriftete, aber\n-- schlechter als keine: Die Beschriftung selbst wird zur nächsten\n-- Falschaussage, sobald jemand sie überliest.\n--\n-- ===========================================================================\n-- Warum die beiden Indizes zuerst fallen\n-- ===========================================================================\n--\n-- SQLite verweigert `ALTER TABLE ... DROP COLUMN`, solange ein Index die\n-- Spalte nennt — gemessen, nicht angenommen:\n--\n--     error in index ix_todo_status after drop column: no such column: board_rank\n--\n-- Deshalb erst die Indizes, dann die Spalte, dann der eine Index, der bleibt.\n--\n-- ---------------------------------------------------------------------------\n-- 1. Die beiden Indizes, die an der Spalte hängen\n-- ---------------------------------------------------------------------------\n--\n-- `ux_todo_rank (status_id, board_rank)` war die Zusicherung „je Statusspalte\n-- eine eindeutige Reihenfolge\". Ohne Ziehen gibt es keine Reihenfolge, die\n-- eindeutig sein müsste; die Zusicherung hat nichts mehr zu sichern.\nDROP INDEX ux_todo_rank;\n\n-- `ix_todo_status (status_id, board_rank)` war der Zugriffspfad „eine Spalte\n-- des Boards, in ihrer Reihenfolge\". Der Filter über `status_id` bleibt\n-- (`TodoFilter.statusIds`, `buildConditions`), und `todo_status` löscht mit\n-- ON DELETE RESTRICT — beides braucht weiterhin einen Index auf `status_id`.\n-- Er wird unten neu angelegt, einspaltig.\nDROP INDEX ix_todo_status;\n\n-- ---------------------------------------------------------------------------\n-- 2. Die Spalte\n-- ---------------------------------------------------------------------------\nALTER TABLE todo DROP COLUMN board_rank;\n\n-- ---------------------------------------------------------------------------\n-- 3. Der Index, der bleibt — einspaltig\n-- ---------------------------------------------------------------------------\n--\n-- Gleicher Name, gleiche Aufgabe, ein Feld weniger. Der Name bleibt absichtlich\n-- derselbe: Ein zweiter Name für denselben Zugriffspfad wäre eine zweite\n-- Auskunft über dieselbe Sache, und `0001_initial.up.sql` nennt ihn ebenso.\nCREATE INDEX ix_todo_status ON todo (status_id);\n",
  "0011_pool_rule_axes.down.sql": "-- Takt — Migration 0011 \"pool_rule_axes\", Rückwärtsrichtung\n-- takt: foreign_keys=off\n--\n-- ===========================================================================\n-- Was der Rückweg zurücknimmt, und was er dabei verliert\n-- ===========================================================================\n--\n-- Zurück bleibt die Form von 0001: eine Liste gleichartiger Tagterme, ein\n-- `match_mode`, sonst nichts. Vier der fünf Achsen haben dort kein Feld, in dem\n-- sie stehen könnten. Deshalb ist dieser Rückweg **nicht verlustfrei**, und der\n-- Verlust ist benannt:\n--\n--   * **Erforderliche Tags** stehen unverändert da, mit unverändertem\n--     `match_mode`. Der Normalfall verliert nichts.\n--   * **Ausgeschlossene Tags** und **Statusterme** fallen weg. Sie lassen sich\n--     in der alten Form nicht ausdrücken.\n--   * **Erledigt** und **Exportstatus** fallen mit ihren Spalten weg.\n--\n-- Eine Regel, die **nur** aus solchen Bedingungen bestand, hat danach eine\n-- leere Regel — und trifft damit nichts (A-3.4). Das ist die richtige Richtung\n-- des Verlusts: Sie ist sichtbar leer. Die Alternative wäre gewesen, solche\n-- Regeln zu löschen, weil sie „vorher nicht existierten\" — das nähme dem\n-- Benutzer eine von Hand eingerichtete Regel samt ihrem Namen und ihrer\n-- Position weg, ohne zu fragen.\n--\n-- Dieselbe Abwägung wie in 0009. Und wie dort gilt: Der eigentliche Rückweg auf\n-- einem benutzten Bestand ist die Sicherungskopie, die der Läufer vor jedem\n-- Lauf anlegt (datenmodell.md 8).\n\nPRAGMA foreign_keys = OFF;\nPRAGMA legacy_alter_table = ON;\n\n-- ---------------------------------------------------------------------------\n-- 1. `pool_rule` zurück in die Form von 0001 — Wort für Wort\n-- ---------------------------------------------------------------------------\nCREATE TABLE pool_rule_alt (\n  pool_id   TEXT NOT NULL REFERENCES pool        (id) ON DELETE CASCADE,\n  tag_id    TEXT          REFERENCES tag         (id) ON DELETE CASCADE,\n  folder_id TEXT          REFERENCES tag_folder  (id) ON DELETE CASCADE,\n  CHECK ((tag_id IS NULL) <> (folder_id IS NULL))     -- genau eine Quelle je Regel\n);\n\n-- Nur die erforderlichen Tagterme. `role = 'excluded'` und `role = 'status'`\n-- haben in dieser Form keinen Platz; siehe Kopf.\nINSERT INTO pool_rule_alt (pool_id, tag_id, folder_id)\nSELECT pool_id, tag_id, folder_id FROM pool_rule WHERE role = 'required';\n\nDROP TABLE pool_rule;\n\nALTER TABLE pool_rule_alt RENAME TO pool_rule;\n\n-- Die drei Indizes aus 0001, wortgleich. `ix_pool_rule_status` kehrt nicht\n-- zurück — die Spalte, auf die er zeigte, gibt es nicht mehr.\nCREATE UNIQUE INDEX ux_pool_rule ON pool_rule (pool_id, COALESCE(tag_id, ''), COALESCE(folder_id, ''));\nCREATE INDEX        ix_pool_rule_tag    ON pool_rule (tag_id)    WHERE tag_id    IS NOT NULL;\nCREATE INDEX        ix_pool_rule_folder ON pool_rule (folder_id) WHERE folder_id IS NOT NULL;\n\n-- ---------------------------------------------------------------------------\n-- 2. Die beiden Spalten an `pool`\n-- ---------------------------------------------------------------------------\n--\n-- Kein Index und kein Trigger hängt an ihnen, deshalb nimmt SQLite das\n-- DROP COLUMN ohne Vorarbeit an — dieselbe Lage wie bei `placement` in 0009.\nALTER TABLE pool DROP COLUMN export_state;\nALTER TABLE pool DROP COLUMN completion;\n\nPRAGMA legacy_alter_table = OFF;\nPRAGMA foreign_keys = ON;\n",
  "0011_pool_rule_axes.up.sql": "-- Takt — Migration 0011 \"pool_rule_axes\", Vorwärtsrichtung\n-- takt: foreign_keys=off\n-- Deckt: A-3.*, A-5.3, A-5.4, E-023, E-032, E-054, T-076\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- ===========================================================================\n-- Wogegen\n-- ===========================================================================\n--\n-- Der Auftraggeber: „ich würde gerne im Kanban Board auch den Status als Regel\n-- mit aufnehmen.\" Und, mit einem Vorbild aus Super Productivity vor Augen:\n-- „Nimm dir ein Beispiel daran. Das regelt das.\"\n--\n-- Bis hierher war eine Regel **eine Liste gleichartiger Terme**: `pool_rule`\n-- mit `tag_id` oder `folder_id`, und `pool.match_mode` sagte, ob eines oder\n-- alle zutreffen müssen. Diese Form kann drei Dinge nicht:\n--\n--   1. **„nicht\"**. Eine Liste gleichartiger Terme hat keinen Platz für ein\n--      ausgeschlossenes Tag. Man müsste das Vorzeichen an den Term hängen und\n--      hätte danach zwei Sorten Term in einer Liste — genau die Bauform, deren\n--      Verknüpfung man erklären muss, statt sie zu lesen.\n--   2. **Größen, die keine Tagmenge sind.** `tag` und `folder` lösen sich\n--      beide zur selben Größe auf: Tagkennungen an `todo_tag`. Der Status tut\n--      das nicht — er steht als `todo.status_id` an der Zeile, genau einer je\n--      Todo. Ebenso „Erledigt\" (`todo.completed_at`) und der Exportstatus, der\n--      an den **Buchungen** hängt und nicht am Todo.\n--   3. **Einen Neutralwert je Bedingung.** In einer Liste ist „diese Bedingung\n--      ist nicht gesetzt\" dasselbe wie „die Liste ist leer\" — und damit war die\n--      leere Regel ein Sonderfall, den jede Auswertung eigens abfangen musste.\n--\n-- Seit dieser Migration hat **jede Bedingung ihr eigenes Feld mit einem\n-- Neutralwert**, und die Verknüpfung folgt aus der Feldstruktur:\n--\n--   erforderliche Tags   pool_rule, role='required'   + pool.match_mode\n--   ausgeschlossene Tags pool_rule, role='excluded'   („keines davon\")\n--   Status               pool_rule, role='status'     („einer von diesen\")\n--   Erledigt             pool.completion              any | done | open\n--   Exportstatus         pool.export_state            any | open | exported\n--\n-- Die Felder sind mit „und\" verbunden. Jedes engt weiter ein; keines kann das\n-- Ergebnis vergrößern.\n--\n-- ===========================================================================\n-- Was mit dem Bestand geschieht — und warum hier nichts geraten wird\n-- ===========================================================================\n--\n-- Die Frage, an der eine solche Umstellung scheitert, lautet: Wird eine\n-- vorhandene Tagliste zu „alle davon\" oder zu „mindestens eines davon\"?\n--\n-- Sie muss hier **nicht beantwortet** werden, weil die Antwort schon dasteht.\n-- `pool.match_mode` hält sie seit Migration 0001, je Regel einzeln:\n--\n--   'any' — mindestens eines. Die Vorgabe der Spalte, die Vorgabe der Route\n--           und die Vorgabe der Oberfläche („Mindestens eines von\").\n--   'all' — alle. Nur, wo jemand es ausdrücklich gewählt hat.\n--\n-- Jede vorhandene Zeile wird deshalb wörtlich zu „erforderliche Tags\" mit\n-- **unverändertem** `match_mode`, und `completion`/`export_state` stehen\n-- neutral. **Jede bestehende Regel trifft nach dieser Migration genau dieselben\n-- Todos wie davor.** Keine Umdeutung, keine Vermutung, kein Bestand, den\n-- jemand nachträglich aufräumen muss.\n--\n-- ===========================================================================\n-- Warum ein Tabellenumbau\n-- ===========================================================================\n--\n-- SQLite kennt kein ALTER TABLE für einen CHECK, und der CHECK aus 0001 —\n-- `(tag_id IS NULL) <> (folder_id IS NULL)` — ist genau die Bedingung, die eine\n-- Zeile mit `status_id` verböte. Der Umbau folgt dem vorgeschriebenen Weg:\n-- neue Tabelle, Inhalt kopieren, alte weg, umbenennen, Indizes wieder anlegen.\n-- Dieselbe Bauart wie in 0006, samt der beiden PRAGMA-Zeilen und ihrer\n-- Begründung.\n--\n-- `pool_rule` hat keine Kindtabelle und kein Trigger hängt daran; der Umbau\n-- ist deshalb einfacher als der in 0006. Die Marke in Zeile 2 wird trotzdem\n-- gebraucht: Ohne sie zöge das RENAME die REFERENCES-Klauseln um, und das DROP\n-- liefe gegen die eingeschaltete Prüfung.\n\n-- Siehe die Begründung im Kopf von 0006: `PRAGMA foreign_keys` ist innerhalb\n-- einer offenen Transaktion wirkungslos und deshalb hier nur für den Fall\n-- wirksam, dass diese Datei ohne den Läufer eingespielt wird — so machen es die\n-- Prüfpfade, die das Schema selbst untersuchen.\nPRAGMA foreign_keys = OFF;\nPRAGMA legacy_alter_table = ON;\n\n-- ---------------------------------------------------------------------------\n-- 1. Die beiden Achsen, die an der Regel selbst hängen\n-- ---------------------------------------------------------------------------\n--\n-- Einwertig, dreiwertig, nie leer — dieselbe Bauform wie `placement` (0009) und\n-- aus demselben Grund wie beim Exportstatus (E-032). Zwei Wahrheitswerte\n-- nebeneinander hätten vier Zustände, und einer davon wäre unsinnig.\n--\n-- `DEFAULT 'any'` ist zweierlei zugleich: der Wert für jede vorhandene Zeile\n-- (SQLite füllt ihn beim ALTER ein) und die Vorgabe für jede künftige. Beides\n-- ist gewollt und dasselbe: Wer eine Achse nicht nennt, lässt sie offen.\n--\n-- Der CHECK ist an dieser Stelle zulässig, anders als PRIMARY KEY und UNIQUE.\nALTER TABLE pool ADD COLUMN completion TEXT NOT NULL DEFAULT 'any'\n  CHECK (completion IN ('any', 'done', 'open'));\n\n-- `export_state` fragt nach dem **Vorhandensein** einer Buchung, nicht nach\n-- einem Zustand des Todos: 'open' heißt „hat mindestens eine abgeschlossene,\n-- offene Buchung\", 'exported' heißt „hat mindestens eine exportierte\". Ein Todo\n-- kann beides zugleich erfüllen und steht dann in beiden Spalten — derselbe\n-- Fall, den E-054 zum Normalfall gemacht hat.\nALTER TABLE pool ADD COLUMN export_state TEXT NOT NULL DEFAULT 'any'\n  CHECK (export_state IN ('any', 'open', 'exported'));\n\n-- ---------------------------------------------------------------------------\n-- 2. `pool_rule` — drei Rollen statt einer Liste\n-- ---------------------------------------------------------------------------\n--\n-- `role` ist der eine Unterscheider, und der CHECK ist erschöpfend: Zu jeder\n-- Rolle gehört genau eine gefüllte Spalte, alles andere ist NULL. Damit gibt es\n-- keine Zeile, deren Bedeutung von der Lesart des Auswerters abhängt.\n--\n-- Ein ausgeschlossener **Status** ist ausdrücklich nicht vorgesehen. Er wäre\n-- eine vierte Rolle für eine Bedingung, die sich ohne sie ausdrücken lässt:\n-- Wer „alles außer Erledigt\" meint, wählt die übrigen Status. Bei Tags ist das\n-- anders — dort sind es Tausende, und „alle außer diesem einen\" ließe sich\n-- nicht aufzählen. Genau deshalb gibt es die Ausschlussliste für Tags und nicht\n-- für Status.\nCREATE TABLE pool_rule_neu (\n  pool_id   TEXT NOT NULL REFERENCES pool        (id) ON DELETE CASCADE,\n  role      TEXT NOT NULL DEFAULT 'required' CHECK (role IN ('required', 'excluded', 'status')),\n  tag_id    TEXT          REFERENCES tag         (id) ON DELETE CASCADE,\n  folder_id TEXT          REFERENCES tag_folder  (id) ON DELETE CASCADE,\n  -- ON DELETE RESTRICT, nicht CASCADE: Ein gelöschter Status, der eine Regel\n  -- stillschweigend entkernt, hinterließe eine Spalte, die aus einem Grund\n  -- leer ist, den niemand mehr sehen kann. `todo.status_id` steht aus\n  -- demselben Grund auf RESTRICT, und `TodoStatusPort.remove` nennt den\n  -- fachlichen Grund, bevor die Datenbank ihn nennen muss.\n  status_id TEXT          REFERENCES todo_status (id) ON DELETE RESTRICT,\n  CHECK (\n       (role IN ('required', 'excluded')\n        AND status_id IS NULL\n        AND ((tag_id IS NULL) <> (folder_id IS NULL)))    -- genau eine Quelle je Tagterm\n    OR (role = 'status'\n        AND status_id IS NOT NULL\n        AND tag_id    IS NULL\n        AND folder_id IS NULL)\n  )\n);\n\n-- Jede vorhandene Zeile wird eine **erforderliche**. Siehe Kopf, Abschnitt\n-- „Was mit dem Bestand geschieht\": Die Verknüpfung steht unverändert in\n-- `pool.match_mode` und wird hier nicht angefasst.\nINSERT INTO pool_rule_neu (pool_id, role, tag_id, folder_id, status_id)\nSELECT pool_id, 'required', tag_id, folder_id, NULL FROM pool_rule;\n\nDROP TABLE pool_rule;\n\nALTER TABLE pool_rule_neu RENAME TO pool_rule;\n\n-- ---------------------------------------------------------------------------\n-- 3. Die Indizes\n-- ---------------------------------------------------------------------------\n--\n-- `ux_pool_rule` trägt jetzt zusätzlich `role` und `status_id`, und beides ist\n-- notwendig, nicht schmückend:\n--\n--   * ohne `status_id` kollidierten zwei **verschiedene** Statusterme derselben\n--     Regel miteinander — beide hätten COALESCE(tag_id,'') = COALESCE(folder_id,'') = '';\n--   * ohne `role` ließe sich dasselbe Tag nicht zugleich erfordern und\n--     ausschließen. Das ist zwar eine unsinnige Regel — sie trifft nichts —,\n--     aber sie ist eine Eingabe des Benutzers und kein Datenbankfehler. Die\n--     Antwort darauf gehört in die Oberfläche, nicht in einen 409.\n--\n-- Der Name bleibt derselbe, weil es derselbe Zugriffspfad und dieselbe\n-- Zusicherung ist: „derselbe Regelteil steht nicht zweimal in derselben Regel\".\n-- `errors.ts` übersetzt ihn unter diesem Namen, und `proof:conflicts` misst das.\nCREATE UNIQUE INDEX ux_pool_rule ON pool_rule\n  (pool_id, role, COALESCE(tag_id, ''), COALESCE(folder_id, ''), COALESCE(status_id, ''));\n\n-- Die drei Rückwärtsrichtungen: „welche Regeln hängen an diesem Tag / diesem\n-- Ordner / diesem Status?\". Die ersten beiden gab es seit 0001, der dritte ist\n-- neu und trägt dieselbe Frage für `TodoStatusPort.remove`.\nCREATE INDEX ix_pool_rule_tag    ON pool_rule (tag_id)    WHERE tag_id    IS NOT NULL;\nCREATE INDEX ix_pool_rule_folder ON pool_rule (folder_id) WHERE folder_id IS NOT NULL;\nCREATE INDEX ix_pool_rule_status ON pool_rule (status_id) WHERE status_id IS NOT NULL;\n\nPRAGMA legacy_alter_table = OFF;\nPRAGMA foreign_keys = ON;\n",
  "0012_pool_rule_restrict.down.sql": "-- Takt — Migration 0012 \"pool_rule_restrict\", Rückwärtsrichtung\n-- takt: foreign_keys=off\n--\n-- ===========================================================================\n-- Was der Rückweg zurücknimmt — und was er dabei nicht verliert\n-- ===========================================================================\n--\n-- Zurück steht die Form von 0011: `tag_id` und `folder_id` auf ON DELETE\n-- CASCADE, `status_id` weiterhin auf RESTRICT.\n--\n-- **Kein Datenverlust.** Anders als die Rückrichtung von 0011 nimmt diese hier\n-- keiner Zeile ihren Platz: Die Tabelle behält dieselben fünf Spalten,\n-- denselben CHECK und denselben Inhalt. Was zurückgenommen wird, ist allein das\n-- Verhalten beim Löschen eines Tags oder eines Ordners.\n--\n-- **Was der Rückweg wieder aufmacht**, und das gehört benannt: Ein gelöschter\n-- Ordner nimmt danach seine Regelterme wieder still mit (R-1 Befund 1). Die\n-- Prüfungen in `TagPort.remove` und `TagFolderPort.remove` bleiben davon\n-- unberührt und weisen weiterhin fachlich ab — der Bestand ist also nicht\n-- ungeschützt, sondern nur wieder auf **eine** Wache statt zweier\n-- zurückgesetzt. Genau das war die Lage bis T-089.\n--\n-- Der Umbau ist derselbe wie in der Vorwärtsrichtung: SQLite kennt kein\n-- ALTER TABLE für eine REFERENCES-Klausel.\n\nPRAGMA foreign_keys = OFF;\nPRAGMA legacy_alter_table = ON;\n\n-- ---------------------------------------------------------------------------\n-- 1. `pool_rule` zurück in die Form von 0011 — Wort für Wort\n-- ---------------------------------------------------------------------------\nCREATE TABLE pool_rule_alt (\n  pool_id   TEXT NOT NULL REFERENCES pool        (id) ON DELETE CASCADE,\n  role      TEXT NOT NULL DEFAULT 'required' CHECK (role IN ('required', 'excluded', 'status')),\n  tag_id    TEXT          REFERENCES tag         (id) ON DELETE CASCADE,\n  folder_id TEXT          REFERENCES tag_folder  (id) ON DELETE CASCADE,\n  status_id TEXT          REFERENCES todo_status (id) ON DELETE RESTRICT,\n  CHECK (\n       (role IN ('required', 'excluded')\n        AND status_id IS NULL\n        AND ((tag_id IS NULL) <> (folder_id IS NULL)))\n    OR (role = 'status'\n        AND status_id IS NOT NULL\n        AND tag_id    IS NULL\n        AND folder_id IS NULL)\n  )\n);\n\nINSERT INTO pool_rule_alt (pool_id, role, tag_id, folder_id, status_id)\nSELECT pool_id, role, tag_id, folder_id, status_id FROM pool_rule;\n\nDROP TABLE pool_rule;\n\nALTER TABLE pool_rule_alt RENAME TO pool_rule;\n\n-- ---------------------------------------------------------------------------\n-- 2. Die Indizes aus 0011, wortgleich\n-- ---------------------------------------------------------------------------\nCREATE UNIQUE INDEX ux_pool_rule ON pool_rule\n  (pool_id, role, COALESCE(tag_id, ''), COALESCE(folder_id, ''), COALESCE(status_id, ''));\n\nCREATE INDEX ix_pool_rule_tag    ON pool_rule (tag_id)    WHERE tag_id    IS NOT NULL;\nCREATE INDEX ix_pool_rule_folder ON pool_rule (folder_id) WHERE folder_id IS NOT NULL;\nCREATE INDEX ix_pool_rule_status ON pool_rule (status_id) WHERE status_id IS NOT NULL;\n\nPRAGMA legacy_alter_table = OFF;\nPRAGMA foreign_keys = ON;\n",
  "0012_pool_rule_restrict.up.sql": "-- Takt — Migration 0012 \"pool_rule_restrict\", Vorwärtsrichtung\n-- takt: foreign_keys=off\n-- Deckt: A-3.*, A-4.5, A-4.6, E-054, E-055, E-057, R-1 Befund 1\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- ===========================================================================\n-- Wogegen\n-- ===========================================================================\n--\n-- `pool_rule.tag_id` und `pool_rule.folder_id` standen seit 0001 auf\n-- ON DELETE **CASCADE**. Damit nimmt das Löschen eines Tags oder eines Ordners\n-- die Regelterme, die ihn nennen, stillschweigend mit — und die Regel bedeutet\n-- danach etwas anderes, ohne dass jemand sie angefasst hat.\n--\n-- Der Fall, an dem es aufgefallen ist (R-1 Befund 1): Die Regel „Tags aus\n-- Ordner Ost **und** Status offen\". Löschbar ist nur ein **leerer** Ordner —\n-- und genau der leere Ordner in einer erforderlichen Achse ist der Fall, um\n-- den es in E-057 geht. Nach dem Löschen heißt die Regel „Status offen\". Sie\n-- trifft **mehr**, als der Benutzer gesagt hat, und das ist wörtlich die\n-- Richtung, die E-057 als die gefährliche bezeichnet: Eine Spalte, die zu viel\n-- zeigt, fällt niemandem auf.\n--\n-- Für Tags war die Lage seit jeher dieselbe; dort verhinderte es allein die\n-- Prüfung in `TagPort.remove` (`tag_in_use`, A-4.5). Eine Zusage, die an einer\n-- einzigen `if`-Zeile im Adapter hängt, ist eine Zusage bis zum nächsten\n-- zweiten Schreibpfad.\n--\n-- ===========================================================================\n-- Was sich ändert: dasselbe Muster wie beim Status (0011)\n-- ===========================================================================\n--\n-- `pool_rule.status_id` steht seit 0011 auf ON DELETE **RESTRICT**, und die\n-- Begründung dort gilt Wort für Wort auch für Tag und Ordner:\n--\n--   „Ein gelöschter Status, der eine Regel stillschweigend entkernt,\n--    hinterließe eine Spalte, die aus einem Grund leer ist, den niemand mehr\n--    sehen kann.\"\n--\n-- Nach dieser Migration verhalten sich alle drei Termspalten gleich:\n--\n--   pool_id   → CASCADE   die Regel selbst geht, ihre Terme gehen mit. Richtig:\n--                         Ein Term ohne Regel ist kein Datensatz, sondern Müll.\n--   tag_id    → RESTRICT  die Datenbank weist ab.\n--   folder_id → RESTRICT  ebenso.\n--   status_id → RESTRICT  unverändert seit 0011.\n--\n-- **Die Datenbank ist dabei die zweite Wache, nicht die erste.** `TagPort.remove`\n-- und `TagFolderPort.remove` fragen vorher und antworten fachlich\n-- (`tag_in_use`, 409, mit den Namen der betroffenen Regeln in `details`). Diese\n-- Migration nimmt der Datenbank nur die Möglichkeit, still zu gehorchen, wenn\n-- eines Tages jemand an der Prüfung vorbeischreibt. Der Unterschied ist der\n-- zwischen „FOREIGN KEY constraint failed\" und einem Bestand, dessen Regeln\n-- etwas anderes bedeuten als gestern.\n--\n-- ===========================================================================\n-- Warum ein Tabellenumbau\n-- ===========================================================================\n--\n-- SQLite kennt kein ALTER TABLE für eine REFERENCES-Klausel. Der Umbau folgt\n-- dem vorgeschriebenen Weg und ist Zeile für Zeile der aus 0011: neue Tabelle,\n-- Inhalt kopieren, alte weg, umbenennen, Indizes wieder anlegen. `pool_rule`\n-- hat keine Kindtabelle, und kein Trigger hängt daran.\n--\n-- Die Marke in Zeile 2 wird gebraucht: Ohne sie zöge das RENAME die\n-- REFERENCES-Klauseln der Nachbartabellen um, und das DROP liefe gegen die\n-- eingeschaltete Prüfung. Siehe die Begründung im Kopf von 0006.\n--\n-- **Keine Zeile ändert ihren Inhalt.** Der Bestand wird eins zu eins kopiert;\n-- was sich ändert, ist allein, was beim Löschen anderswo geschieht.\n\nPRAGMA foreign_keys = OFF;\nPRAGMA legacy_alter_table = ON;\n\n-- ---------------------------------------------------------------------------\n-- 1. Dieselbe Tabelle, drei RESTRICT statt zweier CASCADE\n-- ---------------------------------------------------------------------------\n--\n-- Der CHECK ist der aus 0011, unverändert: Zu jeder Rolle gehört genau eine\n-- gefüllte Spalte, alles andere ist NULL.\nCREATE TABLE pool_rule_neu (\n  pool_id   TEXT NOT NULL REFERENCES pool        (id) ON DELETE CASCADE,\n  role      TEXT NOT NULL DEFAULT 'required' CHECK (role IN ('required', 'excluded', 'status')),\n  tag_id    TEXT          REFERENCES tag         (id) ON DELETE RESTRICT,\n  folder_id TEXT          REFERENCES tag_folder  (id) ON DELETE RESTRICT,\n  status_id TEXT          REFERENCES todo_status (id) ON DELETE RESTRICT,\n  CHECK (\n       (role IN ('required', 'excluded')\n        AND status_id IS NULL\n        AND ((tag_id IS NULL) <> (folder_id IS NULL)))    -- genau eine Quelle je Tagterm\n    OR (role = 'status'\n        AND status_id IS NOT NULL\n        AND tag_id    IS NULL\n        AND folder_id IS NULL)\n  )\n);\n\nINSERT INTO pool_rule_neu (pool_id, role, tag_id, folder_id, status_id)\nSELECT pool_id, role, tag_id, folder_id, status_id FROM pool_rule;\n\nDROP TABLE pool_rule;\n\nALTER TABLE pool_rule_neu RENAME TO pool_rule;\n\n-- ---------------------------------------------------------------------------\n-- 2. Die Indizes — wortgleich mit 0011\n-- ---------------------------------------------------------------------------\n--\n-- Sie fallen mit der Tabelle und werden deshalb neu angelegt. Namen und Form\n-- sind dieselben: Es ist derselbe Zugriffspfad und dieselbe Zusicherung, und\n-- `errors.ts` übersetzt `ux_pool_rule` unter diesem Namen (`proof:conflicts`\n-- misst das).\nCREATE UNIQUE INDEX ux_pool_rule ON pool_rule\n  (pool_id, role, COALESCE(tag_id, ''), COALESCE(folder_id, ''), COALESCE(status_id, ''));\n\n-- Die drei Rückwärtsrichtungen: „welche Regeln hängen an diesem Tag / diesem\n-- Ordner / diesem Status?\". Die ersten beiden tragen ab jetzt zusätzlich die\n-- Prüfung, die RESTRICT bei jedem Löschen anstellt.\nCREATE INDEX ix_pool_rule_tag    ON pool_rule (tag_id)    WHERE tag_id    IS NOT NULL;\nCREATE INDEX ix_pool_rule_folder ON pool_rule (folder_id) WHERE folder_id IS NOT NULL;\nCREATE INDEX ix_pool_rule_status ON pool_rule (status_id) WHERE status_id IS NOT NULL;\n\nPRAGMA legacy_alter_table = OFF;\nPRAGMA foreign_keys = ON;\n",
  "0013_skipped_version.down.sql": "-- Takt — Migration 0013 \"skipped_version\", Rückwärtsrichtung\n--\n-- ===========================================================================\n-- Was der Rückweg zurücknimmt — und was dabei verloren geht\n-- ===========================================================================\n--\n-- Die Spalte fällt, und mit ihr der CHECK, der an ihr hängt.\n--\n-- **Ein Datenverlust, und er gehört benannt:** Eine übersprungene Fassung ist\n-- danach nicht mehr übersprungen. Der Hinweis auf genau diese Fassung\n-- erscheint beim nächsten Lauf wieder. Das ist die richtige Richtung — die\n-- Anwendung meldet zu viel statt zu wenig, und der Benutzer kann erneut\n-- überspringen —, aber es ist keine verlustfreie Rücknahme, und wer sie fährt,\n-- soll das wissen.\n--\n-- Keine andere Spalte, kein Fremdschlüssel und kein bestehender CHECK ist\n-- betroffen: Die Spalte kommt in keinem Index, keiner Sicht, keinem Trigger\n-- und keinem anderen CHECK vor. Genau das ist die Bedingung, unter der SQLite\n-- ein DROP COLUMN überhaupt zulässt — hier ist sie erfüllt, und deshalb reicht\n-- eine Zeile statt eines Tabellenumbaus.\n\nALTER TABLE app_setting DROP COLUMN skipped_version;\n",
  "0013_skipped_version.up.sql": "-- Takt — Migration 0013 \"skipped_version\", Vorwärtsrichtung\n-- Deckt: A-18.10, R-20, E-064 Punkt 5, T-136-4\n-- Der Migrationsläufer setzt PRAGMA foreign_keys vor BEGIN und öffnet die Transaktion selbst.\n--\n-- ===========================================================================\n-- Wozu\n-- ===========================================================================\n--\n-- A-18.10: „Wählt der Benutzer ‚Überspringen', wird genau diese Fassung\n-- übersprungen. Für sie erscheint der Hinweis nicht wieder; eine spätere,\n-- neuere Fassung wird wieder gemeldet.\"\n--\n-- Der Wert muss den Neustart überleben, sonst ist er wertlos: R-20 beschreibt\n-- genau den Fall, dass ein nur für die Sitzung gemerktes Überspringen den\n-- Hinweis beim nächsten Start wiederbringt — und ein Hinweis, den man nicht\n-- loswird, wird ungelesen weggeklickt. Danach übersieht der Benutzer auch die\n-- Meldung, die zählt.\n--\n-- Er steht deshalb **im Bestand** und nicht im Arbeitsspeicher des Dienstes und\n-- nicht im Browserspeicher der Oberfläche. Und er steht in `app_setting`, weil\n-- er eine Einstellung ist wie jede andere: eine Zeile, feste Felder, jede\n-- Einstellung mit einem Typ und einer Migration (E-011). Ein eigener\n-- Schlüssel-Wert-Beutel wäre eine zweite Art, Einstellungen zu führen.\n--\n-- ===========================================================================\n-- Warum ein CHECK, obwohl die Tür ohnehin prüft\n-- ===========================================================================\n--\n-- Der Wert ist **Benutzereingabe** (T-136-4, VG-6): Jeder Prozess mit dem\n-- Sitzungsgeheimnis kann ihn über `PATCH /settings` setzen. Geprüft wird er\n-- deshalb an seiner Tür — beim Schreiben gegen die Form aus A-V-8 und beim\n-- **Lesen** noch einmal, weil ein Bestand aus einer fremden Quelle stammen\n-- kann. Ein ungültiger gespeicherter Wert heißt „nichts übersprungen\" und\n-- führt zu keinem Wurf.\n--\n-- Der CHECK hier ist die zweite Wache und nicht die erste, dieselbe Rolle wie\n-- die RESTRICT-Klauseln aus 0011 und 0012: Er nimmt der Datenbank die\n-- Möglichkeit, still zu gehorchen, wenn eines Tages jemand an der Prüfung\n-- vorbeischreibt.\n--\n-- Er ist bewusst **enger als nichts und weiter als die Domäne**: SQLite kennt\n-- ohne Erweiterung kein REGEXP, GLOB kann die Form nicht vollständig\n-- ausdrücken. Was er trägt, ist der Teil, auf den es hier ankommt — der\n-- **Zeichenvorrat** und die **Länge**:\n--\n--   * Länge zwischen 5 (`0.0.0`) und 94 (9+1+9+1+9+1+64, A-V-8).\n--   * Beginnt mit einer Ziffer, und es kommen mindestens zwei Punkte darin vor.\n--   * Kein Zeichen außerhalb von `0-9`, `A-Z`, `a-z`, `.` und `-`. Damit sind\n--     `/`, `\\`, `?`, `#`, `:`, `@`, `%`, Leerzeichen und Zeilenumbruch\n--     ausgeschlossen (B-18.2), und ein Punktsegment kann nicht entstehen, weil\n--     das erste Zeichen eine Ziffer ist.\n--\n-- Was er **nicht** leistet: `1.2.3.4.5.6` besteht ihn. Die vollständige Form\n-- steht in `packages/domain/src/version.ts` und wird an beiden Türen gefahren;\n-- diese Spalte soll keine zweite, abweichende Meinung darüber führen, was eine\n-- Fassung ist.\n--\n-- ===========================================================================\n-- Warum ALTER TABLE ADD COLUMN und kein Tabellenumbau\n-- ===========================================================================\n--\n-- Es ändert sich keine bestehende Spalte, keine REFERENCES-Klausel und kein\n-- bestehender CHECK. `app_setting` hat weder Trigger noch Sicht, die auf ihr\n-- stünden; die einzige Fremdschlüsselbeziehung (`active_export_template_id`)\n-- bleibt unberührt. Ein Umbau wie in 0011/0012 wäre hier mehr Bewegung als\n-- Änderung — und jede kopierte Zeile ist eine Gelegenheit, etwas zu verlieren.\n--\n-- Der Vorgabewert ist NULL: „nichts übersprungen\". Das ist der Zustand, in dem\n-- jeder bestehende Bestand nach dieser Migration steht, und er ist richtig.\n\nALTER TABLE app_setting ADD COLUMN skipped_version TEXT\n  CHECK (\n    skipped_version IS NULL\n    OR (\n      length(skipped_version) BETWEEN 5 AND 94\n      AND skipped_version GLOB '[0-9]*.[0-9]*.[0-9]*'\n      AND skipped_version NOT GLOB '*[^0-9A-Za-z.-]*'\n    )\n  );\n",
});
